const top_zac = {
  champion: '자크',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 빠르게 다가와 침묵을 걸고 평타를 치려 하니, 적당한 거리를 유지하며 (Q)\'탄성 주먹\'으로 둔화를 먼저 묻히세요. 1~2레벨에는 가렌의 (P)\'인내심\' 회복량이 높으니 무리하게 붙지 말고 (W)\'불안정 물질\'로 가볍게 피해를 주며 조각을 줍는 데 집중하세요. 가렌이 (Q)\'결정타\'를 쓰기 전까지는 거리를 벌려 평타를 맞지 않도록 주의하세요.', lv3: '(Q)\'결정타\' 평타에 맞으면 침묵에 걸려 스킬을 쓸 수 없으니, 침묵당하기 전에 (E)\'새총 발사\'로 먼저 진입해 공중에 띄우고 (W)\'불안정 물질\'로 최대 체력 비례 피해를 입히세요. (E)\'심판\'이 도는 동안에는 계속 붙어 있기보다 거리를 조절해 피해를 줄이세요. 가렌이 (W)\'용기\'를 켜서 피해 감소와 보호막을 얻었을 때는 딜교환을 잠시 멈추고 조각을 흡수해 체력을 회복하세요.', lv6: '(R)\'바운스!\'로 가렌을 띄워 둔화시킨 뒤 (Q)\'탄성 주먹\'까지 연계하고 정글러와 함께 공격하면 킬각을 잡기 편해요. 다만 가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례해 큰 피해를 주니, 체력이 낮아졌을 때는 가렌이 다가오지 못하게 거리를 두세요. 라인을 당겨 두고 정글러가 오면 (E)\'새총 발사\'로 가렌을 띄워 합류 타이밍을 맞추세요.', item: '판금 장화를 신어 가렌의 기본 공격 피해를 줄이세요. 첫 코어 아이템으로는 끝없는 절망을 추천하며, 전투 중 지속적으로 체력을 회복해 가렌의 압박을 버티기 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 방해해야 딜교환 이후 체력 관리를 더 쉽게 할 수 있어요.' },
    '갱플랭크': { lv1: '갱플랭크가 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기려 하니 거리 조절에 신경 쓰세요. (Q)\'탄성 주먹\' 사거리를 활용해 짧게 딜교환을 시도하되 (P)\'불의 심판\' 평타를 맞지 않도록 주의해요. 무리하게 진입하기보다 조각을 모아 체력을 관리하며 버티는 것이 중요해요.', lv3: '갱플랭크의 (W)\'괴혈병 치료\'는 군중 제어를 해제하고 체력을 회복하니 이 스킬이 빠진 것을 확인하고 진입하세요. (E)\'새총 발사\'로 거리를 좁힐 때 주변에 (E)\'화약통\'이 깔려 있다면 폭발 피해를 입지 않도록 위치를 잘 잡아야 해요. (Q)\'탄성 주먹\'으로 먼저 둔화를 걸고 (W)\'불안정 물질\'로 폭발적인 피해를 입히며 싸우세요.', lv6: '(R)\'바운스!\'를 사용해 갱플랭크를 공중으로 띄워 킬각을 노리되 (R)\'포탄 세례\' 범위 안에 오래 머물지 않도록 주의하세요. 갱플랭크가 궁극기로 지역을 장악하면 무리하게 들어가지 말고 라인을 당기며 정글러의 도움을 기다리세요. (E)\'새총 발사\'로 적을 맞히며 조각을 생성해 전투 지속력을 높이는 것이 핵심이에요.', item: '판금 장화는 갱플랭크의 기본 공격 피해를 줄여주어 버티기 좋아요. 첫 코어 아이템으로는 태양불꽃 방패를 올려 체력과 방어력을 확보하세요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복량을 줄여 마무리 피해를 높일 수 있어요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'를 통해 둔화와 함께 지속적으로 견제를 시도해요. (Q)\'탄성 주먹\'을 맞히기 위해 거리를 좁히되 술통이 터지는 위치를 잘 살펴서 피해를 최소화하세요. 초반에는 무리한 딜교환보다는 미니언을 챙기며 체력을 관리하는 것이 좋아요.', lv3: '그라가스의 (E)\'몸통 박치기\'가 빠졌을 때 (E)\'새총 발사\'로 진입하여 싸움을 시작하세요. 그라가스가 (W)\'취중 분노\'를 사용하면 받는 피해가 줄어드니 그 효과가 끝난 뒤에 (W)\'불안정 물질\'을 사용하여 몰아쳐야 해요. (Q)\'탄성 주먹\'으로 그라가스를 붙잡고 조각을 생성하며 전투를 이끄세요.', lv6: '(R)\'바운스!\'로 진입할 때 그라가스의 (R)\'술통 폭발\'에 밀려나지 않도록 위치 선정을 잘해야 해요. 그라가스가 (E)\'몸통 박치기\'를 사용해 공중으로 띄우는 것을 경계하며 정글러의 개입을 유도하세요. (E)\'새총 발사\'로 적을 맞히면 조각이 생성되니 빠르게 흡수하여 체력을 회복하세요.', item: '첫 코어 아이템은 체력을 쌓는 강철심장을 가세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 그라가스의 (P)\'서비스 시간\' 회복을 억제하며 킬각을 잡기에 적합해요.' },
    '그웬': { lv1: '1~2레벨에는 그웬이 (P)\'가위 난도질\'로 체력을 회복하며 길게 싸우는 것을 피하세요. (Q)\'싹둑싹둑!\'의 중앙 고정 피해를 맞지 않도록 옆으로 움직이며 거리를 조절해요. (Q)\'탄성 주먹\'으로 둔화를 걸어 상대의 접근을 늦추고 짧은 딜교환만 하세요.', lv3: '(W)\'신성한 안개\'는 대상 지정 스킬만 막으므로 (E)\'새총 발사\'나 (W)\'불안정 물질\' 같은 범위 공격은 그대로 적중해요. 그웬이 (E)\'돌격가위\'로 진입할 때 (E)\'새총 발사\'로 공중에 띄워 흐름을 끊으세요. 안개 안에서는 그웬의 방어력과 마법 저항력이 오르니 오래 싸우기보다 안개가 사라질 때까지 조각을 모으며 기다리세요.', lv6: '(R)\'바느질\'에 맞으면 둔화되니 먼저 맞지 않도록 위치를 잡고, 그 뒤에 (R)\'바운스!\'로 진입하세요. 튀어 오르는 동안 (W)\'불안정 물질\'을 섞어 피해를 주고 (E)\'새총 발사\'로 마무리 킬각을 잡으세요. 그웬의 (W)\'신성한 안개\'가 빠진 시점에 (Q)\'탄성 주먹\'으로 붙잡아 정글러와 함께 협공하는 것이 효과적이에요.', item: '정령의 형상은 마법 저항력을 높여주고 (P)\'세포 분열\'의 체력 회복량을 늘려줘요. 신발은 강인함으로 군중 제어 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'가위 난도질\'을 통한 그웬의 체력 회복을 억제해야 킬각을 잡기 편해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 멀리서 둔화를 걸며 견제하기 때문에 적절한 거리 조절을 잘해야 해요. 나르가 부메랑을 던진 직후에는 (Q)\'탄성 주먹\'으로 적을 맞힌 뒤 증가한 사거리로 공격해 보세요. 초반에는 무리한 진입보다는 체력을 보존하며 파밍에 집중하는 것이 좋아요.', lv3: '나르의 분노가 차서 메가 나르가 되면 (W)\'쿵쾅\'의 기절을 피하기 위해 거리 유지를 잘해야 해요. 메가 나르의 공격이 부담스러울 때는 (E)\'새총 발사\'로 먼저 진입하여 (W)\'불안정 물질\'로 폭발적인 피해를 입히세요. 나르가 (E)\'폴짝\'으로 도망가려 할 때 (Q)\'탄성 주먹\'으로 붙잡아 추격하는 구도를 만드세요.', lv6: '메가 나르의 (R)\'나르!\'는 적을 밀어내고 둔화를 걸며 벽에 부딪히면 기절시키니 벽 근처에서 싸우다 기절하지 않도록 조심하세요. (R)\'바운스!\'로 적을 띄우면 (P)\'세포 분열\' 조각을 모으기 쉬우니 교전 중에 조각 흡수를 잊지 마세요. 정글러를 부를 때는 (E)\'새총 발사\'로 나르를 띄워 갱킹 호응을 쉽게 만드세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 나르의 기본 공격 피해를 줄이고 체력을 높여 버티기 위해서예요.', spell: '점멸과 점화를 추천해요. 나르가 메가 나르로 변했을 때 강력한 한 방으로 킬을 따내기 위해 점화를 사용하세요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 미니언을 먹으며 성장하려 하니 초반에는 적극적으로 압박하세요. (Q)\'탄성 주먹\'을 활용해 미니언과 함께 나서스를 타격하면 조각을 생성하며 체력을 유지하기 편해요. 나서스가 (Q)\'흡수의 일격\'을 쓰러 올 때 거리를 두어 막타를 놓치게 유도하세요.', lv3: '나서스의 (W)\'쇠약\'은 이동 속도를 늦추니 걸리면 (E)\'새총 발사\'로 거리를 벌리거나 빠르게 진입해 싸움을 끝내세요. (Q)\'탄성 주먹\'으로 적을 붙잡은 뒤 (W)\'불안정 물질\'을 터뜨리고 생성된 조각을 먹어 체력을 회복하는 것이 중요해요. 나서스의 (E)\'영혼의 불길\' 장판 위에서는 방어력이 감소하니 주의하세요.', lv6: '나서스의 (R)\'사막의 분노\'가 켜지면 주변에 마법 피해를 입히고 강력해지니 무리한 교전은 피하세요. (R)\'바운스!\'로 여러 번 공중으로 띄워 적을 교란하며 싸우되 나서스의 (Q)\'흡수의 일격\' 쿨타임이 짧아진 점을 기억하세요. 라인을 밀어 넣어 나서스의 성장을 방해하며 정글러의 개입을 유도하세요.', item: '나서스의 물리 공격을 견디기 위해 판금 장화와 태양불꽃 방패를 추천해요. 태양불꽃 방패는 체력과 방어력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 (P)\'영혼의 포식자\'를 통한 회복을 줄이며 킬각을 보세요.' },
    '녹턴': { lv1: '녹턴의 (Q)\'황혼의 인도자\' 견제를 조심하며 (Q)\'탄성 주먹\'으로 거리를 조절해요. 가까이 붙으면 (P)\'그림자 칼날\' 평타로 추가 피해를 주고 체력을 회복하니, 초반에는 미니언을 안정적으로 챙기는 데 집중하세요.', lv3: '녹턴의 (W)\'어둠의 장막\'에 (Q)\'탄성 주먹\'이 막히지 않도록 주의하며 딜교환을 해요. (E)\'새총 발사\'로 진입할 때 녹턴의 (E)\'말할 수 없는 공포\'가 먼저 걸리지 않도록 주의하며 (W)\'불안정 물질\'로 체력을 관리해요.', lv6: '녹턴이 (R)\'피해망상\'을 쓰면 시야가 줄고 멀리서 돌진해 오니, 체력이 낮을 때는 포탑 근처에서 라인을 받으세요. 녹턴이 돌진해 붙으면 (R)\'바운스!\'로 밀어내고 둔화시킨 뒤 (W)\'불안정 물질\'로 맞서며 조각을 흡수하세요.', item: '판금 장화와 강철심장을 선택해요. 녹턴의 물리 피해를 줄이고 높은 체력을 확보하여 버티기 위해서예요.', spell: '점멸과 점화. 녹턴의 체력을 깎고 패시브 회복을 줄여 킬을 노리기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩과 (Q)\'학살\'의 회복력으로 초반 근접전이 매우 강해요. (Q)\'탄성 주먹\'으로 둔화를 걸며 최대한 거리를 유지하고, 무리하게 붙기보다 웨이브 앞쪽에서 견제하며 버티세요. 1~2레벨에는 짧게 딜교환을 하고 바로 빠지는 리듬을 유지하세요.', lv3: '(E)\'포획\'에 끌려가면 (W)\'마비의 일격\'과 연계되어 큰 피해를 입으니 (E)\'포획\' 사거리 안에 오래 서 있지 마세요. (E)\'새총 발사\'로 진입한 뒤 (W)\'불안정 물질\'을 사용하고 빠르게 빠져나오는 짧은 딜교환을 반복하세요. 다리우스의 (E)\'포획\'이 빠진 타이밍을 노려 적극적으로 압박하세요.', lv6: '(R)\'녹서스의 단두대\'는 출혈 중첩이 높을 때 치명적이니 중첩이 쌓이기 전에 (R)\'바운스!\'로 거리를 벌리거나 빠르게 전투를 끊으세요. 체력이 낮아졌을 때 다리우스가 접근하면 즉시 포탑 쪽으로 이동해 보호를 받으세요. 정글러와 함께 (E)\'새총 발사\'로 진입해 순식간에 제압하는 구도를 만드세요.', item: '판금 장화는 다리우스의 기본 공격 피해를 줄여주어 생존력을 높여줘요. 태양불꽃 방패를 첫 코어로 선택해 체력과 방어력을 챙기며 지속 전투 능력을 보완하세요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 끌어당겨 공격을 시작할 때 탈진을 사용하여 피해량을 줄이고 생존 확률을 높이세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 일직선으로 쏘며 멀리서 견제해요. 미니언 뒤에 서서 (Q)\'과부하\'를 맞는 횟수를 줄이며 체력을 관리하세요. (Q)\'탄성 주먹\'을 활용해 라이즈가 미니언을 먹으러 올 때 짧게 딜교환을 시도하며 거리를 조절해요.', lv3: '라이즈가 (E)\'주문 전이\'를 묻힌 뒤 (W)\'룬 감옥\'을 쓰면 속박될 수 있으니 주의하세요. 라이즈의 (W)\'룬 감옥\'이나 (Q)\'과부하\'가 빠진 타이밍에 (E)\'새총 발사\'로 진입하여 (Q)\'탄성 주먹\'과 (W)\'불안정 물질\'로 연계해요. 라이즈의 스킬이 빠진 순간을 노려야 해요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용해 도망치거나 합류하려 하면 무리하게 따라가지 마세요. (R)\'바운스!\'를 사용해 적을 공중으로 띄우고 (E)\'새총 발사\'를 맞히면 라이즈를 압박하기 좋아요. 라이즈가 궁극기를 쓰면 정글러의 개입을 조심하며 라인을 관리하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 라이즈의 마법 피해를 견디고 전투를 지속하기 위해 헤르메스의 발걸음을 가고 태양불꽃 방패로 체력을 챙기세요.', spell: '점멸과 점화를 추천해요. 라이즈가 거리를 벌리기 전에 (E)\'새총 발사\'와 함께 점화로 빠르게 압박하세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 활용한 근접 교환이 매우 강력하니 미니언과 함께 불타지 않도록 주의하세요. 1~2레벨에는 무리하게 진입하기보다는 거리를 조절하며 체력을 보존하는 데 집중해요. (Q)\'탄성 주먹\'을 사용하여 럼블의 위치를 흔들거나 견제하는 정도로만 활용하세요.', lv3: '럼블이 (W)\'고철 방패\'를 사용하면 피해가 흡수되니 방패가 사라진 뒤에 (E)\'새총 발사\'로 진입하세요. (E)\'전기 작살\'에 맞아 마법 저항력이 낮아지기 전에 (W)\'불안정 물질\'로 빠르게 조각을 생성하며 교환을 마무리해요. 럼블의 열기가 과열되어 스킬을 못 쓰는 타이밍을 노려 (Q)\'탄성 주먹\'과 함께 몰아붙이세요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\' 장판을 깔면 안에서 둔화와 지속 피해를 입으니 장판 위에서 오래 싸우지 마세요. 궁극기가 빠진 직후에 (R)\'바운스!\'로 진입해 적을 띄우고 (W)\'불안정 물질\'을 섞어 쓰세요. 정글러를 부를 때는 럼블이 열기가 과열되어 스킬을 못 쓰는 타이밍을 노리세요.', item: '헤르메스의 발걸음을 신어 럼블의 마법 피해를 견디세요. 정령의 형상을 첫 코어로 가서 체력 회복 효과를 높여 교환을 버텨요.', spell: '점멸과 점화를 추천해요. 럼블은 (W)\'고철 방패\'로 버티며 싸우려 하니 점화로 마무리 피해를 입혀 킬각을 보세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 초반 압박이 강하니 1~2레벨에는 최대한 거리를 유지하세요. (Q)\'탄성 주먹\'으로 레넥톤을 둔화시키며 짧게 견제하고, 상대의 분노가 쌓였을 때 정면으로 붙는 것은 피하세요. 무리하게 교전하기보다 경험치 위주로 받으며 버티는 것이 좋아요.', lv3: '(E)\'자르고 토막내기\'로 진입하는 레넥톤의 움직임을 보고 (E)\'새총 발사\'로 띄워 흐름을 끊어주세요. 분노가 찬 상태의 (W)\'무자비한 포식자\'는 기절 시간이 길고 보호막을 파괴하므로 이 스킬이 빠진 뒤에 교환을 시도하세요. 상대가 붙었을 때 (W)\'불안정 물질\'을 사용해 최대 체력 비례 피해를 입히고 빠르게 빠지세요.', lv6: '(R)\'강신\'을 사용한 레넥톤은 체력이 크게 늘고 분노가 빠르게 쌓이니 궁극기 지속 시간 동안은 주의하세요. 레넥톤의 주요 스킬이 빠진 틈을 타 (R)\'바운스!\'로 진입해 적을 띄우고 둔화시키며 킬각을 잡으세요. (E)\'새총 발사\'로 레넥톤의 진입을 끊거나 정글러와 연계해 적을 띄우는 플레이가 필요해요.', item: '가시 갑옷과 판금 장화를 추천해요. 가시 갑옷으로 (Q)\'양떼 도륙\'의 회복력을 억제하고 판금 장화로 레넥톤의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 체력 회복력이 좋은 자크의 특성을 살려 순간이동으로 라인 복귀를 빠르게 하며 유지력 싸움을 하세요.' },
    '렝가': { lv1: '(Q)\'탄성 주먹\'을 사용하여 렝가의 접근을 늦추고 거리 조절을 하세요. (P)\'보이지 않는 포식자\'를 통한 갑작스러운 도약 공격에 대비하며 첫 웨이브는 경험치 위주로 받으세요.', lv3: '(E)\'새총 발사\'로 진입하기 전에 렝가의 야성이 가득 찼는지 확인하세요. 최대 야성의 (W)\'전투의 포효\'는 군중 제어를 해제하고 (E)\'올가미 투척\'은 속박을 걸 수 있으니 그 상태에서는 무리하게 붙지 마세요. 야성이 낮을 때 (W)\'불안정 물질\'로 피해를 주고 (Q)\'탄성 주먹\'으로 거리를 조절하세요.', lv6: '렝가가 (R)\'사냥의 전율\'로 진입할 때 (R)\'바운스!\'를 사용하여 적을 밀어내고 둔화시키세요. 라인을 당겨서 관리하며 (E)\'새총 발사\'로 렝가의 기습적인 도약을 끊어주세요.', item: '판금 장화와 강철심장을 추천해요. 판금 장화는 렝가의 기본 공격 피해를 줄여주고, 강철심장은 체력을 높여 교전을 오래 버티게 해줘요.', spell: '점멸과 점화를 추천해요. 점멸은 생존과 (E)\'새총 발사\' 연계에 필요하며 점화는 (W)\'전투의 포효\'의 체력 회복을 방해해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'로 돌진하며 (P)\'룬 검\'을 활용해 짧은 교환을 시도해요. 1~2레벨에는 무리하게 싸우지 말고 미니언을 챙기며 거리를 유지하세요. 리븐의 이동기가 빠지는 것을 확인하며 (Q)\'탄성 주먹\'으로 거리를 조절하면 좋아요.', lv3: '리븐이 (E)\'용맹\'으로 피해를 흡수하거나 (W)\'기 폭발\'로 기절을 시도할 때는 맞대응하지 마세요. 리븐의 스킬이 빠진 직후에 (E)\'새총 발사\'로 진입하여 (W)\'불안정 물질\'을 연속해서 맞히는 것이 중요해요. (Q)\'부러진 날개\'의 마지막 타격은 주변 적을 공중으로 띄우니 그 범위를 보고 위치를 잡으세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 공격력과 사거리가 늘고, 재사용하면 잃은 체력에 비례한 원거리 피해를 주니 체력이 낮을 때는 주의하세요. 리븐의 연계가 시작될 때 (R)\'바운스!\'로 밀어내고 둔화시키면 흐름을 끊고 킬각을 노릴 수 있어요. 리븐이 궁극기를 켰을 때는 무리하게 싸우기보다 정글러의 도움을 기다리며 라인을 관리하세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화는 리븐의 기본 공격으로 받는 피해량을 줄여주고 태양불꽃 방패는 전투 시 불사르기 피해를 줄 수 있어요.', spell: '점멸과 점화를 추천해요. 리븐의 (E)\'용맹\'이 빠졌을 때 점화로 피해를 입히고 (R)\'바운스!\' 연계로 확실하게 마무리하세요.' },
    '리산드라': { lv1: '리산드라의 (Q)\'얼음 파편\'은 미니언을 관통해 둔화를 걸기 때문에 미니언 뒤에 숨어도 피해를 입어요. 무리하게 다가가기보다 (Q)\'탄성 주먹\'으로 둔화를 걸며 거리를 조절하고 체력 관리에 집중하세요. 1~2레벨에는 상대의 견제를 최소화하며 경험치만 챙기는 것이 좋아요.', lv3: '리산드라의 (W)\'서릿발\'은 주변 적을 속박하고 속박 중에는 돌진할 수 없으니, 이 스킬이 빠진 것을 확인하고 (E)\'새총 발사\'로 진입하세요. 진입 후에는 (W)\'불안정 물질\'을 사용해 최대 체력 비례 피해를 입히고 조각을 흡수해 체력을 회복하세요. (E)\'얼음갈퀴 길\'로 도망치는 리산드라를 (Q)\'탄성 주먹\'으로 붙잡아 둔화를 거는 것이 중요해요.', lv6: '(R)\'바운스!\'로 진입할 때 리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 무적 상태가 되면 피해를 줄 수 없으니 주의하세요. 상대가 (R)\'얼음 무덤\'으로 나를 기절시키면 정글러의 개입이 쉬워지므로 시야를 잘 확인하며 진입하세요. (E)\'새총 발사\'로 먼저 진입한 뒤 (R)\'바운스!\'를 연계해 리산드라를 공중에 띄워 킬각을 잡으세요.', item: '케이닉 루컨을 첫 코어로 선택해 높은 마법 저항력과 체력을 확보하고 유지력을 높이세요. 신발은 (W)\'서릿발\' 속박과 (R)\'얼음 무덤\' 기절 시간을 줄여주는 헤르메스의 발걸음이 필수예요.', spell: '점멸과 정화를 추천해요. (W)\'서릿발\'의 속박이나 (R)\'얼음 무덤\'의 기절을 정화로 즉시 풀고 역공할 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 마스터 이의 (P)\'2연속 공격\' 평타를 조심하며 거리를 유지하세요. (Q)\'탄성 주먹\'을 활용해 멀리서 견제하며 조각을 모으는 데 집중하고 무리하게 붙어서 싸우지 마세요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용하여 대상으로 지정할 수 없게 되면 스킬을 아껴 두세요. 마스터 이가 (W)\'명상\'을 써서 피해를 줄이며 회복할 때는 (W)\'불안정 물질\'을 아껴 두었다가 스킬이 끝난 뒤에 사용하세요. (E)\'새총 발사\'로 적을 공중으로 띄워 딜교환을 시도하는 것이 좋아요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화 효과가 통하지 않으니 (R)\'바운스!\'를 사용하여 공중으로 띄우는 것에 집중하세요. 마스터 이가 킬을 먹으면 (R)\'최후의 전사\' 지속시간이 늘어나니 라인을 당겨 관리하며 정글러의 도움을 기다리세요. (E)\'새총 발사\'를 활용해 마스터 이의 진입을 끊거나 역습하세요.', item: '첫 코어로 가시 갑옷을 선택해 마스터 이의 기본 공격 피해를 줄이고 회복을 억제하세요. 신발은 마스터 이의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마스터 이의 (W)\'명상\' 회복 효과를 감소시키면 전투에서 이득을 볼 수 있어요.' },
    '마오카이': { lv1: '마오카이가 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복하며 견제해요. (Q)\'덤불 주먹\'에 밀려나면 딜교환이 어려우니 거리 조절을 하며 (W)\'불안정 물질\'로 짧게 피해를 입히세요. 무리하게 붙기보다 미니언 사이에서 조각을 줍고 체력을 유지하며 시간을 보내세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 도약할 때는 대상으로 지정할 수 없으니, 이 스킬이 빠진 것을 확인한 뒤 (E)\'새총 발사\'로 진입하세요. (E)\'묘목 던지기\'가 깔린 수풀은 피하고, 속박에 걸려도 (Q)\'탄성 주먹\'은 사용할 수 있으니 빠르게 적중시켜 둔화를 거세요. (W)\'뒤틀린 전진\'의 속박이 풀리는 타이밍에 맞춰 (W)\'불안정 물질\'을 사용해 피해를 높이세요.', lv6: '(R)\'대자연의 마수\' 벽이 다가올 때는 옆으로 피해 속박을 피하고, 벽이 사라진 뒤 (R)\'바운스!\'로 진입해 둔화를 거세요. (R)\'바운스!\'로 튀어 오르는 동안 (W)\'불안정 물질\'을 섞어 쓰면 강력한 피해를 줄 수 있어요. 마오카이가 정글러를 불러 (R)\'대자연의 마수\'로 연계하려 할 수 있으니 라인을 적절히 당겨서 관리하세요.', item: '대자연의 힘을 첫 코어로 가서 마오카이의 마법 피해를 줄이고 체력을 높이세요. 신발은 마법 저항력을 높이고 속박과 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이가 묘목과 벽으로 라인을 길게 유지하며 압박하니 순간이동으로 복귀해 손해를 줄이세요.' },
    '말자하': { lv1: '말자하가 (Q)\'공허의 부름\'으로 침묵을 걸며 견제하니 거리 조절에 신경 써야 해요. (P)\'공허 태세\'가 켜져 있을 때는 피해가 줄어드니 평타나 (Q)\'탄성 주먹\'으로 보호를 먼저 깨뜨리세요. 1~2레벨에는 말자하의 사거리가 길지만 자크가 접근해서 (Q)\'탄성 주먹\'을 맞히면 충분히 압박할 수 있어요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 공허충이 자크를 공격하므로 주의해야 해요. (E)\'새총 발사\'로 진입할 때 말자하의 (Q)\'공허의 부름\'을 피하는 것이 딜교환의 핵심이에요. (E)\'재앙의 환상\'이 유지되는 동안에는 무리하게 싸우지 말고 조각을 먹으며 버텨야 해요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 말자하의 궁극기가 빠진 것을 확인하고 (E)\'새총 발사\'로 들어가세요. (R)\'바운스!\'로 진입하면 말자하를 밀어내고 둔화시켜 도망가지 못하게 하면서 (W)\'불안정 물질\'을 섞어 쓸 수 있어요. 말자하가 라인을 밀어 넣을 때 정글러를 불러서 (E)\'새총 발사\'로 한 번에 잡아내는 플레이가 필요해요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 말자하의 마법 피해를 견디고 (Q)\'공허의 부름\' 같은 군중 제어 지속 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 차라리 점화로 킬각을 잡는 것이 좋아요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 계속해서 체력을 깎고 이동 속도를 훔치는데, 지정형 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (P)\'화강암 방패\'가 있을 때는 평타 교환이 손해이니 적절히 거리를 유지하며 (P)\'세포 분열\' 조각을 먹어 체력을 회복하세요. 첫 웨이브에서는 무리하게 붙지 말고 체력 관리에 집중하며 2레벨을 기다리세요.', lv3: '(E)\'새총 발사\'로 진입해 (W)\'불안정 물질\'을 터뜨려 최대 체력 비례 피해를 입히는 것이 좋아요. 말파이트가 (E)\'지면 강타\'로 공격 속도를 낮추려 하면 (Q)\'탄성 주먹\'으로 둔화를 걸며 거리를 조절하세요. (W)\'천둥소리\'가 켜진 상태의 평타는 피해가 높으니 짧게 교환한 뒤 빠지세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 (E)\'새총 발사\'나 (Q)\'탄성 주먹\'으로 끊을 수 없으니 주의하세요. 말파이트가 궁극기를 쓴 직후에 (R)\'바운스!\'로 대응해 적을 띄우고 (W)\'불안정 물질\'로 강력한 피해를 넣으세요. 정글러가 올 때 (R)\'멈출 수 없는 힘\'의 사거리 밖에서 대기하다가 틈을 노려 진입하세요.', item: '공허한 광휘를 첫 코어로 선택해 체력과 마법 저항력을 챙기고, 불사르기로 주변 적에게 지속 마법 피해를 주세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 빠르게 합류하여 (R)\'바운스!\'를 이용한 광역 군중 제어로 한타에 기여하세요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 단일 대상에게 적중하면 피해가 훨씬 강해지니 미니언 근처에 서서 피해를 나누어 받으세요. (P)\'암흑 탄생\' 오라가 켜지면 주변 피해가 늘어나니 너무 오래 붙어 있지 말고 (Q)\'탄성 주먹\'으로 거리를 조절하며 견제하세요. 1~2레벨에는 무리하게 진입하지 말고 경험치 위주로 챙기세요.', lv3: '모데카이저의 (E)\'죽음의 손아귀\'에 끌려가면 (Q)\'말살\' 연계로 큰 피해를 입으니, (E)\'죽음의 손아귀\'가 빠진 것을 확인하고 (E)\'새총 발사\'로 진입하세요. (W)\'불멸\' 보호막이 켜지면 교환이 길어질수록 모데카이저가 강해지니 (W)\'불안정 물질\'로 빠르게 피해를 주고 물러나세요. (Q)\'탄성 주먹\'으로 적을 둔화시켜 상대의 스킬 사거리 밖으로 도망가며 딜교환을 유도하세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 순간이동이나 궁극기로 빠져나올 수 없고 수은 장식띠로도 풀 수 없으니, 모데카이저의 궁극기가 빠진 것을 확인하고 교전하세요. 진입할 때는 (R)\'바운스!\'로 먼저 피해를 주고 (W)\'불안정 물질\'로 조각을 모아 체력을 유지하세요. (E)\'죽음의 손아귀\'가 빠진 타이밍에 정글러와 함께 개입하여 빠르게 처치하세요.', item: '마법 저항력을 제공하는 헤르메스의 발걸음을 신어 모데카이저의 피해를 줄이세요. 첫 코어로 케이닉 루컨을 가서 높은 마법 저항력과 체력으로 모데카이저의 마법 피해를 버텨내세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과가 (W)\'불멸\'의 체력 회복량을 줄여주어 킬각을 잡기 편해요.' },
    '문도박사': { lv1: '문도는 (Q)\'오염된 뼈톱\'을 던져 체력을 회복하며 둔화를 걸어요. 이 투사체는 미니언 뒤에 숨어 피하면서 거리를 조절하세요. (Q)\'탄성 주먹\'으로 먼저 접근하여 문도가 (Q)\'오염된 뼈톱\'을 맞히기 전에 짧은 교환을 시도하세요.', lv3: '문도가 (W)\'심장 전기 충격\'을 사용하면 피해를 저장했다가 회복하니 (E)\'새총 발사\'로 거리를 벌리며 기다리세요. (E)\'새총 발사\'로 진입할 때 (Q)\'오염된 뼈톱\'을 맞지 않도록 주의하며 (W)\'불안정 물질\'을 사용해 피해를 입히세요. 문도가 (P)\'가고 싶은 데로 간다\'로 떨어진 통을 주워 체력을 회복하지 못하게 주의하세요.', lv6: '(R)\'최대 투여량\'을 쓴 문도는 체력을 크게 회복하고 이동 속도도 빨라지니 궁극기 사용 직후에는 무리하게 추격하지 마세요. 문도의 궁극기가 빠진 것을 확인한 뒤 (R)\'바운스!\'로 적을 띄우고 (E)\'새총 발사\'로 진입하여 압박하세요. 라인을 밀어넣고 정글러를 호출하여 문도의 회복력을 억제하며 압박하세요.', item: '헤르메스의 발걸음을 가서 문도의 마법 피해를 줄이세요. 첫 코어 아이템은 체력을 높여주는 강철심장을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 문도의 (R)\'최대 투여량\'과 (Q)\'오염된 뼈톱\' 회복을 억제해야 해요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 멀리서 견제하며 (W)\'역병 화살\'을 쌓으려 하니 주의해야 해요. 바루스가 화살을 조준할 때 옆으로 움직여 피하고 (Q)\'탄성 주먹\'의 사거리를 활용해 짧게 딜교하며 체력을 관리하세요.', lv3: '바루스가 (E)\'퍼붓는 화살\'로 지면을 오염시키면 이동 속도가 늦춰지니 그 자리를 피하세요. 바루스가 (Q)\'꿰뚫는 화살\'을 조준하면 옆으로 움직여 피한 뒤 (E)\'새총 발사\'로 빠르게 파고들어 (W)\'불안정 물질\'을 사용하세요.', lv6: '바루스의 (R)\'부패의 사슬\'을 맞으면 이동이 막히므로 (E)\'새총 발사\'를 쓸 때 주의해야 해요. (R)\'바운스!\'를 적중시켜 바루스를 공중에 띄우면 압박하기 좋으니 팀원과 함께 진입하세요.', item: '첫 코어는 체력을 높여주는 강철심장을 가세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 점멸로 거리를 좁혀 (E)\'새총 발사\'를 맞히기 수월하게 만들고 점화로 마무리하세요.' },
    '베인': { lv1: '베인의 (W)\'은화살\' 고정 피해가 위협적이니 거리를 조절하세요. (Q)\'탄성 주먹\'으로 둔화를 묻히며 다가가되 베인이 (Q)\'구르기\'로 피하면 무리하지 마세요. (P)\'세포 분열\' 조각을 챙기며 라인을 받아먹어요.', lv3: '베인이 (E)\'선고\'를 사용해 벽으로 밀어내지 못하도록 지형에서 떨어져 계세요. (E)\'새총 발사\'로 베인을 띄운 뒤 (Q)\'탄성 주먹\'으로 붙잡아 둔화를 이어 가세요. 베인의 (Q)\'구르기\'가 빠진 타이밍에 적극적으로 들어가세요.', lv6: '(R)\'결전의 시간\'을 쓴 베인은 (Q)\'구르기\'로 투명해져서 위치를 찾기 어려워요. (R)\'바운스!\'로 베인을 맞히며 (W)\'불안정 물질\'을 사용해 피해를 주고 체력을 관리하세요. 정글러와 함께 베인의 (E)\'선고\'를 피하며 압박하세요.', item: '판금 장화와 강철심장을 추천해요. 베인의 기본 공격 피해를 줄이고 체력을 높여 버티기 위함이에요.', spell: '점멸과 점화를 추천해요. (E)\'새총 발사\'로 적을 띄운 뒤 점화로 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 달려와 기절을 걸고 (P)\'무자비한 폭풍\'의 추가 마법 피해를 섞으며 싸워요. 초반에는 볼리베어의 돌진을 주의하며 (Q)\'탄성 주먹\'으로 거리를 유지하면서 미니언을 챙기세요. 볼리베어가 (Q)\'번개 강타\'를 사용해 접근할 때 뒤로 물러나며 맞대결을 피하는 것이 중요해요.', lv3: '(W)\'광란의 상처\'로 표식이 남은 상태에서 볼리베어가 체력을 회복하지 못하도록 (E)\'새총 발사\'로 끊어주거나 거리를 벌리세요. (E)\'천공 분열\' 범위 안에서 볼리베어가 보호막을 얻으니 번개가 떨어지는 곳을 피해 (Q)\'탄성 주먹\'으로 견제하세요. 볼리베어의 주요 스킬이 빠졌을 때 (E)\'새총 발사\'로 진입해 (W)\'불안정 물질\'을 사용하며 교환하세요.', lv6: '(R)\'폭풍을 부르는 자\'를 사용한 볼리베어는 포탑을 비활성화하며 다이브를 시도할 수 있으니 체력이 낮을 때 포탑 아래에 머물지 마세요. 볼리베어가 도약한 직후 (R)\'바운스!\'로 대응하며 (Q)\'탄성 주먹\'으로 위치를 확보하세요. 정글러의 도움을 받아 볼리베어가 (R)\'폭풍을 부르는 자\'를 사용한 뒤에 압박하면 좋아요.', item: '판금 장화를 신어 볼리베어의 기본 공격 피해를 줄이세요. 태양불꽃 방패를 첫 코어로 가서 체력과 방어력을 챙기고, 불사르기로 주변 적에게 지속 피해를 주세요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'를 통해 체력을 회복하는 것을 억제하기 위해 점화가 필요해요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제하니 거리 조절에 신경 쓰세요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. 무리하게 진입하지 말고 체력 관리를 하며 (W)\'불안정 물질\'로 조각을 회복하세요.', lv3: '(W)\'피의 웅덩이\' 상태에서는 대상 지정이 안 되니 (Q)\'탄성 주먹\'을 함부로 쓰지 마세요. (E)\'선혈의 파도\'는 미니언이 가로막을 수 있으니 미니언 뒤에 서서 피해를 줄이세요. (W)\'피의 웅덩이\'가 빠진 것을 확인한 뒤 (E)\'새총 발사\'로 진입해 (W)\'불안정 물질\' 피해를 입히세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 즉시 교전을 피하고 뒤로 빠지세요. (W)\'피의 웅덩이\'가 빠진 타이밍에 (R)\'바운스!\'로 진입해 적을 공중에 띄우고 (W)\'불안정 물질\'을 연계하세요. 라인을 밀어 포탑에 붙게 만든 뒤 정글러를 불러 (Q)\'탄성 주먹\'으로 적을 붙잡아 마무리하세요.', item: '대자연의 힘과 헤르메스의 발걸음을 추천해요. 마법 저항력을 높여 (Q)\'수혈\' 피해를 줄이고 강인함으로 (E)\'선혈의 파도\' 둔화 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. (Q)\'수혈\'로 계속 회복하는 블라디미르의 치유량을 점화로 억제해야 킬을 낼 수 있어요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 둔화 지대를 만드니 폭발하기 전에 거리를 조절하세요. (Q)\'탄성 주먹\'으로 뽀삐를 먼저 맞히며 (P)\'세포 분열\' 조각을 모으는 것이 중요해요. 뽀삐가 (P)\'강철의 외교관\' 보호막을 얻기 전에 짧게 교환하며 압박하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 사용하면 (E)\'새총 발사\'로 돌진하는 것이 막히고 이동 스킬도 못 쓰게 되니 주의하세요. 뽀삐의 (W)\'굳건한 태세\'가 빠진 뒤에 (E)\'새총 발사\'와 (Q)\'탄성 주먹\'을 연계하여 진입하세요. (W)\'불안정 물질\'을 사용하여 조각을 흡수하며 체력을 관리하세요.', lv6: '뽀삐가 (R)\'수호자의 심판\'을 사용하면 멀리 날아가므로 충전하는 동안 위치를 잘 잡아야 해요. (R)\'바운스!\'로 적을 공중에 띄울 때 뽀삐의 (W)\'굳건한 태세\'가 켜져 있는지 꼭 확인하세요. 뽀삐의 궁극기에 밀려나지 않도록 라인 관리와 정글 개입에 대비하세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 마법 피해를 입히세요. 신발은 방어력과 기본 공격 피해 감소를 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐의 체력을 깎아 킬각을 잡거나 마무리 피해를 입히기에 좋아요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나 뒤에 있는 적까지 맞히니 미니언 뒤로 피하지 마세요. (Q)\'대량 학살 강타\'는 충전하는 동안 옆으로 움직여 피하고, (Q)\'탄성 주먹\'으로 거리를 조절하며 파밍에 집중하세요.', lv3: '사이온의 (W)\'영혼의 용광로\' 보호막이 켜져 있을 때는 (E)\'새총 발사\'로 무리하게 진입하지 마세요. 보호막이 사라진 시점에 (E)\'새총 발사\'로 진입하여 (W)\'불안정 물질\'을 사용하고, 사이온의 (Q)\'대량 학살 강타\'는 옆으로 움직여 피하세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진하면 옆으로 비켜서서 충돌을 피한 뒤 (R)\'바운스!\'로 응수하세요. 사이온은 (P)\'영광스러운 죽음\'으로 쓰러진 뒤에도 잠시 되살아나 빠르게 공격하니, 처치한 직후에는 거리를 벌려 피하세요.', item: '태양불꽃 방패를 첫 코어로 올리고 신발은 헤르메스의 발걸음을 신으세요. 사이온의 (Q)\'대량 학살 강타\' 기절과 (E)\'학살자의 포효\' 둔화 지속시간을 줄여줘요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 밀어 넣는 힘이 강하니 순간이동으로 라인 복귀를 도와 손해를 줄이세요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 견제하고 (P)\'페트리사이트 폭발\'이 충전된 평타로 압박해요. 1~2레벨에는 (Q)\'탄성 주먹\'으로 둔화를 걸며 거리를 조절하고 미니언을 챙기세요. 사일러스의 사슬이 교차하는 지점을 피하면서 (Q)\'탄성 주먹\'을 맞히기 위한 준비를 해야 해요.', lv3: '(W)\'국왕시해자\'로 체력을 회복하려는 사일러스를 (Q)\'탄성 주먹\'으로 붙잡아 딜교환을 끊어 주세요. (E)\'도주 / 억압\'의 재사용 사슬에 맞으면 공중에 뜨니 사슬이 날아오는 방향을 피하세요. 스킬이 빠진 것을 확인한 뒤 (E)\'새총 발사\'와 (W)\'불안정 물질\'로 폭발적인 피해를 입히세요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'바운스!\'를 가져가면 역으로 큰 피해를 입을 수 있으니 조심해야 해요. (E)\'새총 발사\'로 먼저 진입한 뒤 (R)\'바운스!\'를 사용하여 사일러스의 움직임을 둔화시키고 띄우세요. 사일러스가 (W)\'국왕시해자\'를 쓰며 버티려 할 때 정글러의 도움을 받아 확실하게 처치하세요.', item: '헤르메스의 발걸음을 가서 사일러스의 마법 피해를 줄이고 강인함을 챙기세요. 첫 코어 아이템은 태양불꽃 방패를 추천해요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 막기 위해 점화가 필요해요.' },
    '세주아니': { lv1: '(Q)\'탄성 주먹\'으로 툭툭 치며 견제하세요. (Q)\'혹한의 맹습\'에 맞으면 공중에 뜨니 거리 조절을 잘 해야 해요. 초반에는 무리하게 붙지 말고 조각을 주우며 체력을 관리하세요.', lv3: '(E)\'새총 발사\'로 진입한 뒤 (W)\'불안정 물질\'로 피해를 입히세요. 세주아니가 (W)\'혹한의 서릿발\'로 중첩을 쌓아 (E)\'만년 서리\'로 기절시키지 못하게 짧게 딜교환하세요. (Q)\'탄성 주먹\'으로 상대를 둔화시켜 거리 조절을 주도하세요.', lv6: '(R)\'빙하 감옥\'에 맞으면 바로 기절하므로 주의하며 진입하세요. (R)\'바운스!\'로 적을 띄워 올린 뒤 (W)\'불안정 물질\'을 연계해 킬각을 보세요. 정글 개입 시 세주아니의 강력한 군중 제어기에 먼저 노출되지 않도록 조심하세요.', item: '헤르메스의 발걸음과 끝없는 절망을 가세요. 강인함으로 기절과 둔화 지속시간을 줄이고 전투 중 체력을 회복해 버티기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 빠르게 합류하고 점멸을 (E)\'새총 발사\'와 연계해 기습적인 진입을 하기 위해서예요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 이동 속도를 높여 다가오며 평타에 최대 체력 비례 피해를 얹어요. 자크는 (Q)\'탄성 주먹\'의 사거리를 활용해 세트가 접근하기 전에 거리를 조절하며 미니언과 함께 맞히는 것이 좋아요. 세트의 (Q)\'주먹다짐\'이 빠진 타이밍에 (Q)\'탄성 주먹\'으로 둔화를 걸며 교환하세요.', lv3: '세트가 (E)\'안면 강타\'로 자크를 끌어당겨 기절시키려 할 때 조심해야 해요. 세트의 (W)\'강펀치\'는 받은 피해를 투지로 저장해 보호막을 얻고 고정 피해를 입히니, 투지가 가득 찼을 때 무리하게 들어가지 마세요. 세트의 (W)\'강펀치\'를 (E)\'새총 발사\'로 피하거나 거리를 벌린 뒤, (Q)\'탄성 주먹\'과 (W)\'불안정 물질\'로 딜교환을 시도하세요.', lv6: '세트의 (R)\'대미 장식\'은 자크를 붙잡아 제압하고 내리꽂으니, 사용될 때 근처에 있지 마세요. 자크는 (R)\'바운스!\'로 적을 공중에 띄우고 (W)\'불안정 물질\'을 섞어 피해를 줄 수 있으니, 세트의 (W)\'강펀치\'가 빠진 것을 확인하고 진입하세요. 세트가 (R)\'대미 장식\'을 사용해 강제로 싸움을 걸면 (E)\'새총 발사\'를 사용해 거리를 벌리며 정글러를 부르세요.', item: '첫 코어로 태양불꽃 방패를 가서 체력과 방어력을 챙기며 지속 싸움을 준비하세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 세트는 (P)\'투기장의 투지\'로 잃은 체력에 비례해 체력을 회복하니 점화로 회복을 줄이세요.' },
    '쉔': { lv1: '쉔이 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주며 (P)\'기 보호막\'을 얻어 끈질겨요. 쉔이 스킬을 사용해 보호막이 생겼을 때는 무리하게 붙지 말고 보호막이 사라진 뒤에 (W)\'불안정 물질\'로 피해를 입히세요. 기의 검이 날아오는 경로를 피해 거리를 유지하며 조각을 흡수해 체력을 관리하세요.', lv3: '(E)\'그림자 돌진\'에 도발되면 스킬을 쓸 수 없으니 쉔의 돌진이 빠진 것을 확인하고 (E)\'새총 발사\'로 진입하세요. (W)\'의지의 결계\'가 켜지면 평타가 막히므로 (Q)\'탄성 주먹\'의 다음 기본 공격을 아꼈다가 결계가 끝난 뒤에 사용하세요. 쉔이 (Q)\'황혼 강습\'을 사용해 강화 평타를 치려 할 때 (W)\'불안정 물질\'을 섞어 짧게 딜교환하고 빠지세요.', lv6: '쉔이 (R)\'단결된 의지\'로 아군을 도우러 떠나면 빠르게 라인을 밀어 포탑에 압박을 주세요. (R)\'바운스!\'를 사용해 쉔을 띄우고 (W)\'불안정 물질\'을 계속 터뜨려 체력을 깎으세요. 다만 쉔이 (E)\'그림자 돌진\'으로 내 진입을 끊어 도발할 수 있으니 거리 조절에 주의하세요.', item: '태양불꽃 방패를 첫 코어로 가서 체력과 방어력을 높이고 라인 정리 능력을 갖추세요. 신발은 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 합류하는 속도에 맞춰 빠르게 대응하기 위해 필요해요.' },
    '쉬바나': { lv1: '쉬바나가 (Q)\'잉걸불 일격\'을 사용하며 압박할 때 거리를 유지하며 미니언을 챙기세요. (Q)\'탄성 주먹\'을 활용해 상대의 접근을 늦추며 파밍에 집중하는 것이 좋아요. 초반에는 무리하게 싸우기보다 조각을 모으는 데 신경 써야 해요.', lv3: '상대의 (E)\'용암 분출\'에 맞으면 둔화되니 이를 피하며 (E)\'새총 발사\'로 진입할 타이밍을 노려야 해요. 쉬바나가 (W)\'지옥불 방패\'로 보호막을 켜면 무리하게 딜교환하지 말고 조각을 흡수하며 버티세요. 스킬을 맞춘 뒤 (W)\'불안정 물질\'로 피해를 입히고 빠지는 것이 효과적이에요.', lv6: '쉬바나가 (R)\'용의 강림\'으로 변신하여 들어올 때는 (R)\'바운스!\'를 사용하여 상대의 진입을 받아치세요. 변신한 상태의 쉬바나는 매우 강력하므로 정글러를 호출하여 함께 상대하는 것이 안전해요. 라인을 밀어넣은 뒤에는 조각을 활용해 체력을 관리하며 다음 교전을 준비하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 가세요. 마법 저항력을 얻고 불사르기 피해를 입히기 위해서예요.', spell: '점멸과 점화. 상대의 체력을 깎아 마무리하고 체력 회복을 방해하기 위해서예요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 멀리서 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'죽음의 손길\'을 피하면서 (Q)\'탄성 주먹\'으로 미니언을 챙기며 체력을 보존하세요. 초반에 스웨인이 (Q)\'죽음의 손길\'로 체력을 많이 깎으면 딜교환을 피해야 해요.', lv3: '스웨인이 (E)\'속박명령\'을 쓰면 파동이 돌아올 때 옆으로 피해 속박을 피하세요. (E)\'속박명령\'이 빠진 순간 (E)\'새총 발사\'로 진입하여 (W)\'불안정 물질\'을 터뜨리면 효과적이에요. (W)\'제국의 눈\'에 맞으면 모습이 드러나니 주의하며 (Q)\'탄성 주먹\'으로 거리를 조절하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용하면 주변에서 생명력을 흡수하므로 무리하게 맞서지 마세요. 승천은 챔피언을 흡수하는 동안 이어지니 오래 붙어 있지 말고 짧게 교환하세요. 변신한 상태에서는 (E)\'새총 발사\'로 조각을 만들고 흡수해 체력을 회복하며 버텨야 해요.', item: '스웨인의 마법 피해를 견디기 위해 헤르메스의 발걸음을 먼저 구매하세요. (P)\'세포 분열\'로 체력을 회복할 때 도움이 되는 정령의 형상을 첫 코어로 맞춰요.', spell: '점멸과 점화를 추천해요. 점화로 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'의 체력 회복 효과를 줄여야 해요.' },
    '스카너': { lv1: '스카너의 (Q)\'부서진 대지/지반 돌출\' 투사체와 강화 평타가 강한 구간이니 거리를 조절하며 파밍하세요. (E)\'새총 발사\'로 무리하게 진입하기보다 (W)\'불안정 물질\'을 활용해 조각을 모으며 체력을 관리하는 것이 중요해요.', lv3: '스카너가 (W)\'대지의 수호자\'로 보호막을 얻었을 때 무리하게 들어가지 말고 스킬이 빠지기를 기다려요. (Q)\'탄성 주먹\'으로 스카너를 붙잡은 뒤 (E)\'새총 발사\'를 맞춰 에어본을 시키면 딜교환을 원활하게 할 수 있어요.', lv6: '스카너의 (R)\'꿰뚫기\' 제압에 걸리면 대응이 어려우니 (R)\'바운스!\'를 사용하여 스카너의 접근을 방해하세요. (E)\'새총 발사\'로 스카너를 먼저 띄워 킬각을 잡고, 라인을 밀어 넣은 뒤 정글러와 함께 압박하세요.', item: '헤르메스의 발걸음과 정령의 형상. 스카너의 마법 피해를 줄이고 군중 제어 지속시간을 낮추기 위해 선택해요. 마법 저항력을 효율적으로 확보할 수 있어요.', spell: '점멸과 점화. (E)\'새총 발사\'로 거리를 좁히거나 (R)\'바운스!\' 이후에 스카너의 체력을 낮추기 위해 사용해요. 적을 확실히 마무리하기 위해 필요해요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 깔아 지속 피해를 주며 라인을 압박해요. 독구름 위에서는 피해를 계속 입으니 구름을 피해 미니언을 챙기세요. 신지드는 근처 챔피언을 피할 때 (P)\'독성 급류\'로 빨라지니 무리하게 쫓지 말고 (Q)\'탄성 주먹\'으로 둔화를 걸어 붙잡으세요.', lv3: '신지드의 (W)\'초강력 접착제\'에 닿으면 이동 스킬을 쓸 수 없으니 (E)\'새총 발사\'를 사용하기 전 위치를 잘 잡으세요. 신지드가 (E)\'던져넘기기\'를 사용하면 (Q)\'탄성 주먹\'으로 다시 붙잡아 (W)\'불안정 물질\'로 딜교환을 시도하세요. 접착제가 빠진 후 (E)\'새총 발사\'로 신지드를 띄우는 것이 핵심이에요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 (Q)\'맹독의 자취\'로 고통스러운 상처를 남기니 맞대결을 피하세요. (R)\'바운스!\'로 신지드를 띄운 뒤 (W)\'불안정 물질\'을 사용하여 적을 압박하고 (P)\'세포 분열\' 조각을 흡수해 체력을 관리하세요. 신지드가 라인을 밀 때 (E)\'새총 발사\'로 진입하여 정글러의 도움을 받으세요.', item: '첫 코어로 체력과 마법 저항력을 주는 공허한 광휘를 가세요. 신발은 마법 피해를 견디고 강인함을 얻는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (W)\'초강력 접착제\'를 피해 접근하거나 신지드의 체력을 빠르게 깎아 마무리하기 좋아요.' },
    '아이번': { lv1: '1~2레벨에는 아이번의 (Q)\'덩굴뿌리\'에 속박되지 않도록 미니언 뒤에 숨거나 거리를 유지하며 파밍해요. 아이번이 (W)\'수풀 가꾸기\'를 사용하여 시야를 가리면 무리하게 진입하지 말고 미니언 근처에서 안전하게 움직이세요. (E)\'새총 발사\'의 충전 시간을 활용해 상대의 움직임을 주시하며 기회를 기다려요.', lv3: '3레벨 이후에는 (E)\'새총 발사\'로 진입하여 아이번의 (Q)\'덩굴뿌리\'를 피하거나 맞춘 뒤 (Q)\'탄성 주먹\'으로 이어지는 콤보를 시도해요. 아이번이 (E)\'보호의 씨앗\'을 사용해 보호막을 얻는 타이밍을 확인하고 (W)\'불안정 물질\'로 체력을 관리하며 딜교환을 진행하세요. 상대의 주요 스킬이 빠진 직후에 거리를 좁히는 것이 좋아요.', lv6: '6레벨 이후에는 (R)\'바운스!\'를 사용하여 아이번과 데이지를 동시에 공중으로 띄워 변수를 만드세요. 데이지의 공격을 조심하며 (E)\'새총 발사\'로 진입한 뒤 (W)\'불안정 물질\'을 사용해 (P)\'세포 분열\' 조각을 챙기며 버티는 것이 중요해요. 정글러가 근처에 있다면 아이번의 (R)\'데이지!\' 소환 직후에 강하게 압박하며 라인을 관리하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 아이번의 마법 피해와 군중 제어 지속시간을 줄이기 위해 헤르메스의 발걸음을 가고 태양불꽃 방패로 체력을 높여요.', spell: '점멸과 점화. (E)\'새총 발사\'로 진입할 때 점멸을 활용해 거리를 좁히고 점화로 킬 결정력을 높여요.' },
    '아지르': { lv1: '아지르가 (Q)\'사막의 맹습\'으로 멀리서 견제하니 무리하게 다가가지 마세요. (P)\'세포 분열\'로 생성된 조각을 잘 흡수하며 체력을 관리해요. 미니언을 먹으며 거리를 조절하며 다음 단계를 준비하세요.', lv3: '아지르의 (W)\'일어나라!\' 공격이 보이면 (E)\'새총 발사\'를 사용해 빠르게 접근하세요. 아지르가 (E)\'신기루\'로 거리를 벌리려고 하면 무리하지 말고 뒤로 물러나요. (Q)\'탄성 주먹\'으로 적을 붙잡아 딜교환을 시작해요.', lv6: '(R)\'바운스!\'를 사용해 아지르에게 돌진하면 킬각을 볼 수 있어요. 아지르가 (R)\'황제의 진영\'으로 밀어낼 수 있으니 진입 타이밍을 신중히 정하세요. 정글러가 오면 (E)\'새총 발사\'로 아지르를 공중으로 띄워 갱킹을 도와요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 아지르의 마법 피해를 견디기 위해 헤르메스의 발걸음을 가고 체력을 높여주는 태양불꽃 방패를 선택해요.', spell: '점멸과 점화예요. (R)\'바운스!\'로 들어갈 때 점멸을 사용하고 점화로 아지르를 마무리해요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 견제하며 (P)\'암살자의 표식\' 원을 넘나들어 평타 피해를 주려 해요. (Q)\'탄성 주먹\'으로 아칼리를 붙잡아 둔화시키면 거리를 좁히기 편하고, (P)\'세포 분열\' 조각을 계속 흡수하며 버티세요. 아칼리가 기력을 다 쓸 때까지 최대한 거리 조절을 하며 피해를 최소화하세요.', lv3: '(W)\'황혼의 장막\' 안의 아칼리는 대상 지정이 안 되니 (W)\'불안정 물질\'과 (E)\'새총 발사\'처럼 범위로 공격하는 스킬로 대응하세요. 아칼리가 (E)\'표창곡예\' 표식을 남기고 돌진하기 전에 먼저 (E)\'새총 발사\'로 띄워 흐름을 끊어주는 것이 중요해요. (Q)\'탄성 주먹\'으로 적을 붙잡아 (W)\'불안정 물질\' 피해를 확실히 입히세요.', lv6: '(R)\'무결처형\'의 두 번째 돌진은 잃은 체력에 비례해 큰 피해를 주니 체력이 낮을 때 무리하게 진입하지 마세요. (R)\'바운스!\'로 아칼리를 띄워 이동 경로를 방해하고 주변 아군과 함께 공격하며 압박하세요. 라인을 밀어두고 정글러와 함께 아칼리를 구석으로 몰아 (E)\'새총 발사\' 연계로 킬각을 잡으세요.', item: '정령의 형상을 첫 코어로 올려 마법 저항력과 체력을 챙기고 (P)\'세포 분열\'의 회복량을 높이세요. 신발은 아칼리의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진으로 아칼리의 폭발적인 피해량을 줄이고 진입 시 시간을 벌 수 있어요.' },
    '아크샨': { lv1: '아크샨의 (Q)\'복수의 부메랑\' 사거리가 길어서 초반 견제가 강하니 거리를 잘 조절해야 해요. 미니언을 끼고 파밍하며 (Q)\'탄성 주먹\'을 맞힐 기회를 천천히 노리세요. 무리하게 진입하기보다 조각을 모으는 데 집중하며 버텨야 해요.', lv3: '(Q)\'탄성 주먹\'을 먼저 맞춰 둔화를 건 뒤 (E)\'새총 발사\'로 진입하는 구도를 만드세요. 아크샨이 (E)\'영웅의 비상\'으로 도망갈 수 있으니 스킬을 미리 빼게 유도해야 해요. (W)\'불안정 물질\'을 섞어 최대한 많은 조각을 생성하며 싸우세요.', lv6: '(R)\'바운스!\'로 적을 공중에 띄운 뒤 (W)\'불안정 물질\'을 연계하여 압박하세요. 아크샨의 (R)\'인과응보\'는 잃은 체력에 비례한 피해를 주니 체력이 낮을 때 주의해야 해요. 라인을 당겨두고 정글러와 함께 아크샨을 노리는 것이 좋아요.', item: '판금 장화와 강철심장을 선택하세요. 아크샨의 기본 공격 피해를 줄이고 체력을 높여 전투를 길게 가져가기 위해서예요.', spell: '점멸과 점화예요. (E)\'새총 발사\'로 진입할 때 위치를 잡고 아크샨의 체력을 빠르게 깎기 위해서예요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\' 끝자락에 맞으면 피해가 크고 공중에 뜨니 최대한 범위를 피해 서세요. (P)\'사신 태세\'가 적용된 평타는 체력을 회복하니 1~2레벨에는 평타 교환을 피하며 경험치만 챙기세요. 틈이 보일 때 (Q)\'탄성 주먹\'으로 둔화시키며 짧게 딜교환하고 빠지세요.', lv3: '(W)\'지옥사슬\'에 맞으면 지역을 벗어나지 않았을 때 중앙으로 끌려가니 표시가 보이면 즉시 거리 조절을 하세요. (E)\'파멸의 돌진\'으로 (Q)\'다르킨의 검\' 위치를 조정하는 타이밍을 읽고 (E)\'새총 발사\'로 진입해 공중에 띄우세요. 진입 후에는 (W)\'불안정 물질\'을 사용해 최대 체력 비례 피해를 입히고 빠르게 빠지세요.', lv6: '(R)\'세계의 종결자\'를 켠 아트록스는 체력 회복량이 크게 늘어나니 정면에서 오래 싸우지 말고 거리를 벌리세요. (R)\'바운스!\'로 적을 밀쳐내며 진입해 (W)\'불안정 물질\'을 섞어 쓰면 상대의 회복량을 상회하는 피해를 줄 수 있어요. (P)\'세포 분열\' 조각을 계속 흡수하며 유지력을 높이고 정글러와 함께 덮쳐 킬각을 보세요.', item: '가시 갑옷과 판금 장화를 추천해요. 가시 갑옷은 기본 공격에 맞을 때 치유 감소를 걸어 상대의 회복을 억제하고, 판금 장화는 방어력과 기본 공격 피해 감소를 줘요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과가 (E)\'파멸의 돌진\'과 (P)\'사신 태세\'를 통한 아트록스의 체력 회복을 막는 데 효과적이에요.' },
    '암베사': { lv1: '암베사가 (P)\'용사냥개의 발걸음\'으로 짧게 돌진하며 평타를 강화하니 1~2레벨에는 무리하게 붙지 마세요. (Q)\'교활한 휩쓸기\'의 사거리를 의식하며 거리를 조절하고, 상대가 미니언을 먹으러 올 때 (Q)\'탄성 주먹\'으로 견제하며 체력을 관리하세요.', lv3: '암베사가 (W)\'배척\'으로 보호막을 얻고 준비하는 동안에는 (W)\'불안정 물질\'을 아껴 두었다가 보호막이 사라진 뒤에 쓰세요. (E)\'찢어 가르기\'로 둔화를 걸고 들어올 때 (E)\'새총 발사\'로 먼저 공중에 띄우면 딜교환을 이끌어낼 수 있어요. 상대의 (P)\'용사냥개의 발걸음\' 돌진 타이밍을 보고 (Q)\'탄성 주먹\'을 맞히는 것이 중요해요.', lv6: '암베사가 (R)\'공개 처형\'을 사용해 제압하면 스킬을 쓸 수 없으니, 상대의 궁극기 사거리 안에서 갑자기 튀어나가지 않도록 주의하세요. (R)\'공개 처형\'은 저지 불가 상태로 순간 이동하니 끊으려 하지 말고, 궁극기가 빠진 뒤 (R)\'바운스!\'로 진입하며 정글러를 부르세요. 라인을 밀어 넣고 시야를 확보하며 암베사가 (R)\'공개 처형\'을 낭비하도록 유도하는 것이 좋아요.', item: '첫 코어로 태양불꽃 방패를 가서 체력과 방어력을 챙기세요. 신발은 암베사의 기본 공격 피해를 줄이기 위해 판금 장화를 추천해요.', spell: '점멸과 탈진을 추천해요. 암베사가 (E)\'찢어 가르기\'로 붙어 오거나 (R)\'공개 처형\'의 제압이 끝난 직후 탈진을 걸면 암베사의 피해량을 크게 줄일 수 있어요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'을 사용해 멀리서 둔화와 기절을 걸며 견제해요. 구체가 터지는 지점을 피해 이동하며 거리를 유지하고, (Q)\'탄성 주먹\'으로 거리를 좁힐 준비를 하며 체력을 관리하세요.', lv3: '애니비아가 (W)\'결정화\'로 앞길을 막으면 접근이 어려우니 벽이 사라진 뒤에 (E)\'새총 발사\'로 진입하세요. (Q)\'냉기 폭발\'을 맞았다면 바로 (Q)\'탄성 주먹\'으로 붙어서 (W)\'불안정 물질\'을 사용해 딜교환을 하세요.', lv6: '(R)\'얼음 폭풍\' 장판 안에서는 계속 둔화와 피해를 받으니 오래 머물지 말고 빠르게 벗어나세요. 애니비아가 (P)\'환생\'으로 부활할 수 있으니 (R)\'바운스!\'로 띄워 처치한 뒤 알을 빠르게 공격하세요.', item: '헤르메스의 발걸음과 강철심장을 추천해요. 마법 저항력과 강인함으로 애니비아의 군중 제어 효과를 줄이고 체력을 높여 전투를 오래 지속하세요.', spell: '점멸과 점화를 추천해요. (P)\'환생\'한 애니비아를 빠르게 마무리하기 위해 점화를 사용하세요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'을 통해 원거리에서 견제하며 (P)\'낭인의 길\' 보호막을 쌓으려 해요. (Q)\'탄성 주먹\'의 사거리를 활용해 미니언 사이에서 안전하게 거리를 조절하며 야스오의 접근을 차단하세요. 1~2레벨에는 무리하게 진입하기보다 체력을 관리하며 파밍에 집중하는 것이 좋아요.', lv3: '야스오가 (W)\'바람 장막\'을 사용해 투사체를 막으려 할 때 (E)\'새총 발사\'로 돌진하면 벽을 무시하고 진입할 수 있어요. (Q)\'강철 폭풍\'의 회오리가 쌓이기 전에 (Q)\'탄성 주먹\'으로 야스오를 잡아 거리를 좁히거나 둔화를 거세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 도망가기 전에 스킬을 적중시켜야 해요.', lv6: '야스오는 공중에 뜬 적 챔피언에게 (R)\'최후의 숨결\'을 쓰니, 아군이 띄워진 상태에서 야스오 근처에 서지 않도록 조심하세요. (R)\'바운스!\'는 적을 띄우고 둔화시키니 야스오가 (E)\'질풍검\'으로 도망치려 할 때 맞혀 킬각을 잡으세요. 상대 정글러가 띄우는 스킬을 가졌다면 라인을 너무 깊게 밀지 않도록 주의하세요.', item: '판금 장화는 야스오의 기본 공격 피해를 줄여줘요. 태양불꽃 방패는 근접 전투에서 지속적인 피해를 입히기 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 거리를 좁히고 점화로 야스오의 (P)\'낭인의 길\' 보호막 이후 남은 체력을 깎아 마무리하세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 공격을 하며 방어력을 낮추니 거리를 조절해야 해요. (Q)\'탄성 주먹\'을 활용해 오공의 접근을 막으며 조각을 모을 준비를 하세요. 1~2레벨에는 무리하게 싸우기보다 미니언을 챙기며 차분하게 대응해요.', lv3: '오공이 (E)\'근두운 급습\'으로 돌진해 들어올 때 (E)\'새총 발사\'를 맞춰 공중으로 띄우면 딜교환을 주도할 수 있어요. 오공이 (W)\'분신 전사\'를 사용해 투명해지면 분신에 (Q)\'탄성 주먹\'을 낭비하지 않도록 주의하세요. 오공의 (Q)\'파쇄격\'이 빠진 타이밍에 (W)\'불안정 물질\'을 섞어서 피해를 입히세요.', lv6: '오공이 (R)\'회전격\'을 써서 주변 적을 공중에 띄우려 할 때 (R)\'바운스!\'로 빠르게 대응하며 맞서세요. 공중에 뜨면 스킬을 쓸 수 없으니 오공의 궁극기가 시작되기 전에 (E)\'새총 발사\'를 맞히는 것이 중요해요. 오공의 (W)\'분신 전사\'와 궁극기가 연계될 때 정글러의 개입이 올 수 있으니 라인을 적절히 관리하세요.', item: '오공의 물리 피해를 줄여주는 판금 장화와 체력을 높여주는 강철심장을 추천해요. 이 조합은 유지력과 방어력을 동시에 챙겨줘요.', spell: '점멸과 점화를 추천해요. 점화로 오공에게 추가 피해를 입혀서 킬을 노리세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'를 던져 견제하고 (P)\'영혼 방호술\'로 체력을 회복하니 거리 조절에 유의하세요. 첫 웨이브에서는 최대한 피해를 덜 입으며 버티고, (Q)\'탄성 주먹\'을 통해 둔화를 걸며 딜교환 기회를 엿보세요. (Q)\'이중 저주\'가 돌아오는 경로를 피해 옆으로 움직이며 피해를 최소화하세요.', lv3: '(E)\'마법의 문\'으로 둔화가 걸린 뒤 오로라가 뒤로 도약하니 무리하게 쫓지 말고, 도약 방향을 예상해 (Q)\'탄성 주먹\'으로 붙잡으세요. 오로라가 (W)\'장막 너머로\'를 사용해 투명해지면 무리하게 진입하지 말고 조각을 흡수하며 버티세요. (W)\'불안정 물질\'은 오로라가 근접했을 때 빠르게 사용해 최대 체력 비례 피해를 입히세요.', lv6: '(R)\'세계의 경계\' 영역 안에서는 오로라가 빠르게 이동하므로 영역 밖으로 밀어내거나 빠르게 탈출하는 것이 중요해요. 오로라의 (E)\'마법의 문\'이 빠진 시점에 (R)\'바운스!\'로 진입해 공중에 띄우고 (W)\'불안정 물질\'로 강력한 피해를 입히세요. 라인을 밀어 넣고 정글러를 부를 때 (Q)\'탄성 주먹\'으로 상대를 붙잡아 갱킹 성공률을 높이세요.', item: '대자연의 힘을 첫 코어로 가서 마법 저항력을 높이세요. 마법 피해를 여러 번 받으면 마법 저항력과 이동 속도가 더 늘어나 접근하기 좋고, 신발은 오로라의 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. (E)\'새총 발사\'와 함께 점멸을 사용해 변칙적인 진입 각을 만들고 순간이동으로 빠른 라인 복귀를 하세요.' },
    '오른': { lv1: '오른은 (Q)\'용암 균열\'로 원거리에서 둔화를 걸며 견제하니 기둥이 생기는 위치를 피하세요. 1~2레벨에는 무리하게 싸우기보다 미니언을 챙기며 (Q)\'탄성 주먹\'으로 적의 체력을 깎는 것에 집중하세요.', lv3: '오른이 (E)\'화염 돌진\'으로 벽에 부딪히면 공중으로 띄우니 벽 근처에서는 조심하세요. 오른의 (W)\'불꽃 풀무질\'을 맞으면 불안정 상태가 되어 이동 불가 효과가 길어지니 전진하는 방향을 잘 피하세요. 오른의 스킬이 빠진 것을 확인한 뒤 (E)\'새총 발사\'로 진입하여 (W)\'불안정 물질\'을 사용하세요.', lv6: '오른의 (R)\'대장장이 신의 부름\'은 정령이 지나가며 둔화와 불안정 상태를 만드니 정령의 진행 방향을 미리 파악하세요. 오른이 재사용으로 정령에 박치기하면 방향이 바뀐 정령이 적을 띄우니, 그 경로를 피한 뒤 (R)\'바운스!\'로 맞받아치세요. 오른은 (P)\'간이 대장간\'으로 아이템을 강화하니 라인 관리를 통해 성장을 억제하세요.', item: '판금 장화와 강철심장을 가세요. 판금 장화로 오른의 기본 공격 피해를 줄이고 강철심장으로 체력을 높여 전투를 길게 가져가기 위해서예요.', spell: '점멸과 유체화를 추천해요. 적에게 빠르게 접근하여 전투를 시작하기에 적합해요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'로 도끼를 던져 둔화시키고 방어력을 깎으려 할 거예요. 도끼를 피하며 (Q)\'탄성 주먹\'으로 짧게 견제하고 거리 조절을 하세요. 올라프가 도끼를 주우러 올 때 너무 깊게 붙으면 (P)\'광전사의 분노\'로 인한 공격 속도 증가 때문에 위험해요.', lv3: '올라프가 (W)\'버티기\'로 보호막을 얻었을 때는 (W)\'불안정 물질\'을 사용해 최대 체력 비례 피해를 입히며 버티세요. (E)\'무모한 강타\'의 고정 피해가 강력하니 정면에서 오래 싸우지 말고 (E)\'새총 발사\'로 빠르게 진입했다가 빠지세요. (Q)\'탄성 주먹\'으로 올라프를 둔화시켜 (E)\'무모한 강타\'의 사거리를 주지 않는 것이 중요해요.', lv6: '올라프가 (R)\'라그나로크\'를 켜면 모든 이동 방해 효과에 면역이 되므로 (R)\'바운스!\'나 (E)\'새총 발사\'를 써도 띄울 수 없어요. (R)\'라그나로크\'가 끝나기를 기다렸다가 (R)\'바운스!\'로 공중에 띄우고 (W)\'불안정 물질\'로 피해를 넣으세요. 체력이 낮을수록 (P)\'광전사의 분노\' 흡혈이 강해지니 정글러와 함께 확실하게 마무리하세요.', item: '판금 장화를 신어 올라프의 기본 공격 피해를 줄이세요. 가시 갑옷을 첫 코어로 가서 방어력을 높이고 (P)\'광전사의 분노\'로 인한 회복력을 깎으세요.', spell: '점멸과 점화를 추천해요. 올라프의 (P)\'광전사의 분노\' 생명력 흡수를 점화의 치유 감소로 억제해야 해요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'으로 일직선 견제를 하고 (P)\'사냥꾼의 길\'로 두 번째 공격마다 마법 피해를 입혀요. (Q)\'필멸의 검\' 중첩이 쌓여 돌풍에 띄워지지 않도록 거리를 조절하세요. (Q)\'탄성 주먹\'으로 요네를 둔화시키며 첫 웨이브를 안전하게 받아내세요.', lv3: '요네가 (E)\'영혼해방\'을 사용해 진입하면 다시 육신으로 돌아가는 지점에 (E)\'새총 발사\'를 맞춰 공중으로 띄우세요. (W)\'영혼 가르기\'로 보호막을 얻기 전에 (W)\'불안정 물질\'을 사용해 최대 체력 비례 피해를 입히세요. (Q)\'필멸의 검\' 돌풍이 빠진 뒤 (Q)\'탄성 주먹\'으로 둔화시켜 짧은 딜교환을 유도하세요.', lv6: '(R)\'바운스!\'를 사용해 튀어 오르는 동안 (W)\'불안정 물질\'을 계속 섞어 피해를 입히세요. (R)\'운명봉인\'은 경로의 적을 끌어당기니 팀원과 너무 가깝게 서 있지 않도록 조심하세요. 요네가 (E)\'영혼해방\'으로 들어왔다가 돌아가는 타이밍에 (R)\'바운스!\'를 연계하면 킬각을 잡기 편해요.', item: '끝없는 절망과 판금 장화를 추천해요. 판금 장화로 요네의 기본 공격 피해를 줄이고 끝없는 절망의 체력과 방어력으로 버티며 지속적으로 체력을 회복하세요.', spell: '점멸과 순간이동을 추천해요. (R)\'바운스!\'와 점멸을 연계해 변수를 만들고 순간이동으로 빠르게 라인에 복귀하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 무덤을 생성하며 기본 공격으로 압박을 가해요. (P)\'영혼의 길잡이\' 안개 망령이 주변에서 공격하므로 무작정 붙기보다는 (Q)\'탄성 주먹\'으로 거리를 조절하며 딜교환하세요. 첫 웨이브에서는 상대의 무덤 생성을 억제하며 체력을 보존하는 것이 중요해요.', lv3: '요릭이 (E)\'애도의 안개\'를 맞히면 망령들이 몰려오니 구체를 피해 거리 조절을 하세요. (W)\'망자의 진\' 벽에 막히면 벽을 공격해 부수거나 돌아서 접근하세요. 요릭의 스킬이 빠진 틈을 타 (W)\'불안정 물질\'로 광역 피해를 입히며 짧게 치고 빠지는 구도가 편해요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 지속 싸움이 힘들어지니 주의하세요. (R)\'바운스!\'로 요릭과 마녀를 동시에 띄워 진형을 붕괴시키고 정글러의 개입을 유도하세요. 마녀의 표식이 남았을 때는 무리하게 진입하지 말고 (Q)\'탄성 주먹\'으로 적절한 거리를 유지하며 라인을 관리하세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화로 요릭의 기본 공격 피해를 줄이고 태양불꽃 방패의 지속 피해로 소환물들을 빠르게 정리하세요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'최후의 의식\'의 회복량을 줄여야 딜교환에서 앞설 수 있어요.' },
    '우디르': { lv1: '우디르는 (Q)\'야생 발톱\'으로 기본 공격 피해를 늘려 초반 평타 교환이 강해요. (E)\'불길 쇄도\'를 사용해 빠르게 다가와 기절시키려 하니, 평타 사거리를 주지 말고 (Q)\'탄성 주먹\'으로 거리를 유지하며 견제하세요. 첫 웨이브에서는 무리하게 붙지 말고 조각을 모으며 체력을 관리하세요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막을 얻고 체력을 회복하니, 보호막이 사라진 뒤에 (W)\'불안정 물질\'로 최대 체력 비례 피해를 입히세요. (E)\'불길 쇄도\'의 기절이 빠진 뒤에 (E)\'새총 발사\'로 진입해야 기절에 끊기지 않고 적을 띄울 수 있어요. (Q)\'탄성 주먹\'으로 적을 둔화시켜 우디르의 추격 속도를 늦춘 뒤 딜교환을 마무리하세요.', lv6: '우디르가 (E)\'불길 쇄도\'를 재사용하면 이동 불가와 이동 방해 효과에 면역이 되니, 그동안은 (R)\'바운스!\'나 (E)\'새총 발사\'로 띄우려 하지 말고 끝나기를 기다리세요. (R)\'날개 돋친 폭풍\'의 둔화가 부담되므로 (W)\'불안정 물질\'로 빠르게 피해를 주고 조각을 흡수해 빠져나오세요. 정글러를 호출할 때는 (E)\'새총 발사\'로 우디르의 도주 경로를 차단하며 호응하세요.', item: '가시 갑옷과 판금 장화를 가세요. (W)\'강철 갑옷\'의 체력 회복을 억제하고 (Q)\'야생 발톱\'의 기본 공격 피해를 줄여야 해요.', spell: '점멸과 점화를 추천해요. (W)\'강철 갑옷\'의 강력한 체력 회복을 점화로 억제해 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 견제하니, 폭약이 떨어지는 위치를 보고 옆으로 피하세요. 무리하게 진입하기보다 (W)\'불안정 물질\'을 활용해 짧게 딜교환하고 조각을 흡수해 체력을 관리하세요. 초반에는 상대의 원거리 공격에 노출되지 않도록 거리 조절에 집중하세요.', lv3: '(E)\'새총 발사\'로 진입할 때 우르곳의 (E)\'경멸\'에 맞으면 뒤로 던져지며 기절하니, 상대의 돌진기가 빠진 것을 확인하고 진입하세요. (Q)\'탄성 주먹\'으로 먼저 거리를 좁힌 뒤 (W)\'불안정 물질\'을 연계해 피해를 입히고 빠르게 빠지세요. 우르곳이 (W)\'심판의 원\'을 켰을 때는 정면에서 버티지 말고 빠르게 거리를 벌리세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 상태에서 체력이 낮아지면 제압당해 처형되니, 체력 관리에 유의하고 거리 조절을 하세요. (R)\'바운스!\'로 진입해 적을 띄우고 (W)\'불안정 물질\'을 섞어 공격하되, 상대의 (E)\'경멸\' 위치를 잘 살펴야 해요. 라인을 밀어 넣은 뒤 정글러를 호출해 우르곳의 도주 경로를 차단하고 함께 공격하세요.', item: '판금 장화를 신어 우르곳의 기본 공격 피해를 줄이세요. 끝없는 절망을 첫 코어로 가서 체력과 방어력을 높이고 전투 중 지속적으로 체력을 회복하세요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력이 중요하고 정글 개입에 빠르게 대응하며 운영의 이점을 챙기세요.' },
    '워윅': { lv1: '1~2레벨에는 워윅이 (Q)\'야수의 송곳니\'로 도약해 피해를 주고 체력을 회복하니 무리하게 붙지 마세요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 회복량이 늘어나니 거리를 조절하며 미니언을 챙기세요. (Q)\'탄성 주먹\'으로 워윅을 끌어당기기보다는 안전하게 파밍을 우선시해요.', lv3: '워윅의 (E)\'원시의 포효\'가 켜진 동안에는 피해 감소 효과가 있으니 (E)\'새총 발사\'로 바로 진입하지 마세요. 워윅의 (Q)\'야수의 송곳니\'를 피하면서 (Q)\'탄성 주먹\'으로 거리를 좁히고 (W)\'불안정 물질\'을 사용해 딜교환을 해요. 자크의 체력이 절반 아래로 떨어지면 워윅이 (W)\'피의 사냥\'으로 이동 속도와 공격 속도를 얻으니 주의하세요.', lv6: '워윅이 (R)\'무한의 구속\'을 사용하면 제압 상태가 되어 어떤 스킬도 사용할 수 없으니 정면에서 마주치지 않도록 조심하세요. (R)\'바운스!\'를 활용해 적절한 거리에서 진입하여 워윅을 공중으로 띄우고 (W)\'불안정 물질\'로 체력을 회복하며 싸우세요. 워윅의 궁극기가 빠졌을 때 적극적으로 싸워야 해요.', item: '첫 코어로 태양불꽃 방패를 올리고 신발은 헤르메스의 발걸음을 선택하세요. 워윅의 마법 피해를 견디고 (E)\'원시의 포효\'의 공포 지속 시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'에 의한 체력 회복을 줄여야 해요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. 미니언 체력이 낮은 곳에 서 있으면 계속 진입을 허용하니 위치를 조심하고 (Q)\'탄성 주먹\'으로 둔화를 걸어 거리 조절을 하세요. 1~2레벨에는 무리하게 붙지 말고 조각을 모으며 버티는 것이 좋아요.', lv3: '(E)\'쌍검협무\'의 두 칼날이 교차하는 경로를 피해 기절과 표식을 허용하지 마세요. 표식이 남으면 (Q)\'칼날 쇄도\'가 초기화되어 계속 공격받으니 주의하고, 상대가 진입했을 때 (W)\'불안정 물질\'로 피해를 입히세요. (E)\'새총 발사\'로 적을 공중에 띄우면 이렐리아의 공격 흐름을 끊을 수 있어요.', lv6: '(R)\'선봉진격검\'에 맞으면 불안정 표식이 남아 (Q)\'칼날 쇄도\'가 초기화되고, 결계를 지나가면 피해와 둔화를 받으니 이 궁극기가 빠질 때까지 교전을 피하세요. (R)\'바운스!\'로 진입하며 (W)\'불안정 물질\'을 섞어 쓰면 강력한 피해를 줄 수 있지만, (Q)\'칼날 쇄도\'로 도망갈 수 있으니 주의하세요. 정글러가 왔을 때 (E)\'새총 발사\'로 이렐리아를 띄워 연계하면 킬각을 잡기 편해요.', item: '판금 장화와 끝없는 절망을 추천해요. 판금 장화로 기본 공격 피해를 줄이고, 끝없는 절망의 체력과 방어력으로 버티며 지속 피해를 입히세요.', spell: '점멸과 점화를 추천해요. 점화로 이렐리아의 (Q)\'칼날 쇄도\'를 통한 체력 회복을 억제하며 딜교환을 하세요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에 촉수를 소환해 공격하니 최대한 벽에서 떨어진 중앙 지역에서 싸우세요. 1~2레벨에는 (Q)\'탄성 주먹\'으로 거리 조절을 하며 일라오이가 (Q)\'촉수 강타\'를 허공에 썼을 때 짧게 딜교환을 하세요. 촉수 피해를 줄이기 위해 무리하게 붙지 말고 경험치만 챙기며 버티세요.', lv3: '일라오이의 (E)\'영혼의 시험\'에 맞으면 내 영혼이 분리되고, 일라오이가 그 영혼을 때리면 피해 일부가 나에게 들어오니 (E)\'새총 발사\'를 쓰기 전에 (E)\'영혼의 시험\'이 빠졌는지 확인하세요. 영혼에서 멀어지면 내가 숙주가 되어 촉수 피해를 받으니 거리에 주의하세요. (W)\'혹독한 가르침\'으로 붙으려는 일라오이는 (Q)\'탄성 주먹\'으로 둔화시켜 거리를 유지하세요.', lv6: '(R)\'믿음의 도약\'은 주변에 수많은 촉수를 소환하므로 일라오이가 궁극기를 쓴 뒤에는 (R)\'바운스!\'로 밀쳐내거나 빠르게 범위를 벗어나세요. 촉수가 없는 평지에서 (E)\'새총 발사\'와 (R)\'바운스!\'를 연계해 적을 띄우면 일라오이의 반격을 최소화하며 킬각을 잡을 수 있어요. 일라오이가 벽 근처에서 버티며 정글 개입을 기다릴 수 있으니 라인을 적절히 당겨서 관리하세요.', item: '끝없는 절망을 첫 코어로 선택해 체력을 높이고 전투 중 지속적으로 체력을 회복하며 버티세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. (E)\'영혼의 시험\' 사거리에서 빠르게 벗어나거나 (R)\'바운스!\'의 각도를 잡기 위해 점멸이 필요하고, 라인 복귀를 위해 순간이동을 사용하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 공격하며 체력을 회복하니 정면 평타 싸움은 피하세요. 무리하게 붙기보다 거리를 유지하며 (Q)\'탄성 주먹\'으로 툭툭 건드려 주세요. (P)\'전쟁 단련\' 중첩이 쌓이면 공격력이 올라가니 짧은 교환만 하세요.', lv3: '자헨의 (W)\'공포의 귀환\'에 끌려가면 연속 공격을 맞으니 직선 경로에서 벗어나세요. (E)\'찬란한 쇄도\'로 들어오는 순간에 맞춰 (E)\'새총 발사\'로 띄워 흐름을 끊어 주세요. (W)\'불안정 물질\'을 적절히 섞어 자헨의 (P)\'전쟁 단련\' 중첩을 쌓기 전에 피해를 입히세요.', lv6: '자헨이 (R)\'단호한 판결\'로 높게 날아오르면 낙하 지점에서 빠르게 벗어나세요. (R)\'바운스!\'를 사용해 자헨을 밀어내고 (W)\'불안정 물질\'로 지속 피해를 입히면 처치 기회를 만들 수 있어요. (P)\'전쟁 단련\'으로 부활할 수 있으니 체력이 다해도 방심하지 마세요.', item: '강철심장과 판금 장화를 추천해요. 강철심장의 체력으로 자헨과의 교환을 버티고, 판금 장화로 자헨의 강력한 평타 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 자헨이 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '잭스': { lv1: '잭스는 (Q)\'도약 공격\'으로 빠르게 접근해 (P)\'가차없는 맹공\'을 활용한 평타 교환을 시도해요. (Q)\'탄성 주먹\'을 사용해 거리를 조절하며 잭스의 체력을 미리 깎아두는 것이 좋아요. 1~2레벨에는 무리하게 들어가기보다 미니언을 챙기며 다음 타이밍을 준비하세요.', lv3: '잭스가 (E)\'반격\'을 사용하면 잠시 거리를 두어 기절에 걸리지 않게 주의하세요. 잭스의 (E)\'반격\'이 끝난 직후에 (E)\'새총 발사\'로 진입하여 (W)\'불안정 물질\'을 맞히며 딜교환을 하세요. (Q)\'탄성 주먹\'으로 적을 붙잡은 뒤 (W)\'불안정 물질\'을 사용하면 더 효과적으로 조각을 생성할 수 있어요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 얻으면 정면 승부는 피하는 것이 좋아요. (R)\'바운스!\'로 잭스를 밀쳐내거나 공중에 띄워 진형을 붕괴시키며 싸우세요. 정글러를 호출할 때는 (E)\'새총 발사\'로 먼저 진입하여 잭스의 (Q)\'도약 공격\'을 빼놓는 것이 도움이 돼요.', item: '첫 코어로 태양불꽃 방패를 가서 지속적인 전투 능력을 높이세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 잭스가 (Q)\'도약 공격\'으로 들어와 딜교환을 시작할 때 탈진을 사용하면 피해량을 줄일 수 있어요.' },
    '제이스': { lv1: '제이스가 캐논 형태의 (Q)\'전격 폭발\'로 계속 견제하니 투사체의 궤적을 피해 피해를 최소화하며 버티세요. (E)\'새총 발사\'를 사용할 때는 제이스가 (Q)\'전격 폭발\'을 쓴 직후의 빈틈을 노려 진입하세요. 무리하게 다가가기보다 조각을 모으며 체력을 관리하는 것이 중요해요.', lv3: '제이스의 (E)\'천둥 강타\'에 밀려나면 딜교환이 어려우니, 해머 형태의 스킬이 빠진 것을 확인하고 (Q)\'탄성 주먹\'으로 붙으세요. (E)\'가속 관문\'을 통한 강력한 포킹을 피한 뒤 (E)\'새총 발사\'로 진입해 (W)\'불안정 물질\'로 피해를 입히세요. (Q)\'전격 폭발\'의 궤적을 피하며 거리 조절을 하는 것이 핵심이에요.', lv6: '(R)\'바운스!\'로 진입해 제이스를 띄우면 킬각을 잡기 편해요. 다만 (R)\'머큐리 캐논\' 변환 직후의 기본 공격은 방어력을 깎으니 정면 충돌은 피하세요. 제이스가 (E)\'천둥 강타\'로 밀어내기 전에 (Q)\'탄성 주먹\'을 먼저 맞혀 둔화시킨 뒤 추격하세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화로 제이스의 기본 공격 피해를 줄이고, 태양불꽃 방패의 체력과 방어력으로 버티며 주변 적에게 피해를 입히세요.', spell: '점멸과 순간이동을 추천해요. (E)\'새총 발사\'의 사거리를 보완해 기습적으로 진입하고, 라인 복귀를 빠르게 하세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 지면을 파열시켜 공중에 띄우고 둔화를 주니 지면 표시를 보고 피하세요. (E)\'날카로운 가시\'는 정면의 적을 둔화시키므로 초가스의 정면에 서서 오래 싸우지 마세요. 1~2레벨에는 (Q)\'탄성 주먹\'을 적중시켜 둔화를 걸며 거리를 조절하는 것이 좋아요.', lv3: '초가스의 (W)\'흉포한 울부짖음\'에 침묵을 당하면 (E)\'새총 발사\'를 바로 쓸 수 없으니 주의해야 해요. 상대의 (Q)\'파열\'이 빗나간 것을 확인하고 (E)\'새총 발사\'로 파고들어 딜교환을 하세요. (Q)\'탄성 주먹\'으로 초가스를 붙잡은 뒤 (W)\'불안정 물질\'을 연계해 피해를 입히세요.', lv6: '초가스의 (R)\'포식\'은 방어력을 무시하는 고정 피해를 주므로 체력이 낮을 때는 멀리 떨어져 있으세요. (R)\'바운스!\'로 진입하면서 (W)\'불안정 물질\'을 사용하면 초가스에게 큰 피해를 줄 수 있어요. 초가스가 (Q)\'파열\'로 공중에 띄우려 할 때를 조심하며 전투를 진행하세요.', item: '심연의 가면을 첫 코어로 가고 헤르메스의 발걸음을 신으세요. 심연의 가면은 마법 저항력을 높여주며, 헤르메스의 발걸음은 (W)\'흉포한 울부짖음\'의 침묵과 (Q)\'파열\'의 둔화를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\'을 통한 체력 회복 효과를 줄이세요.' },
    '카밀': { lv1: '카밀은 챔피언을 기본 공격하면 (P)\'적응형 방어 체계\'로 보호막을 얻으니 1~2레벨 평타 교환은 짧게 끊고 거리를 조절하세요. (Q)\'탄성 주먹\'을 활용해 멀리서 견제하며 카밀이 (Q)\'정확성 프로토콜\'로 붙지 못하게 하세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\' 바깥쪽 절반에 맞으면 둔화되고 카밀이 체력을 회복하니 안쪽으로 파고드는 것이 좋아요. 카밀이 (E)\'갈고리 발사\'로 벽을 타고 들어올 때 (E)\'새총 발사\'를 맞춰 기절을 끊어주세요.', lv6: '카밀이 (R)\'마법공학 최후통첩\'으로 가두면 갇힌 지역 내에서 빠져나가기 어려우니 주의하세요. 카밀이 궁극기를 쓰기 전에 (E)\'새총 발사\'나 (R)\'바운스!\'로 먼저 진입해 팀과 함께 교전을 시작하세요.', item: '첫 코어로 강철심장을 가서 체력을 높이세요. 신발은 기본 공격으로 받는 피해량을 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 카밀이 (W)\'전술적 휩쓸기\'를 통해 체력을 회복하는 것을 줄이세요.' },
    '카사딘': { lv1: '카사딘의 (Q)\'무의 구체\'로 들어오는 견제를 주의하며 미니언과 함께 움직여요. (Q)\'탄성 주먹\' 사거리를 활용해 적절한 거리에서 압박을 가하며 조각을 모을 준비를 하세요.', lv3: '자크의 (E)\'새총 발사\'로 진입할 때 카사딘의 (E)\'힘의 파동\'이 둔화를 거는 것을 조심하세요. (Q)\'탄성 주먹\'으로 먼저 적을 붙잡고 (W)\'불안정 물질\'로 피해를 입히며 조각을 흡수하는 것이 좋아요.', lv6: '카사딘이 (R)\'균열 이동\'으로 거리를 벌리기 전에 (R)\'바운스!\'를 적중시켜 공중에 띄워야 해요. (E)\'새총 발사\'로 거리를 좁힌 뒤 궁극기를 연계하여 정글러와 함께 압박을 시도하세요.', item: '헤르메스의 발걸음과 강철심장을 선택해요. 카사딘의 마법 피해를 견디고 체력을 높여 전투를 길게 가져가기 위해서예요.', spell: '점멸과 점화를 선택해요. 카사딘의 (R)\'균열 이동\'에 대응하여 거리를 조절하고 적을 확실히 마무리하기 위해서예요.' },
    '카시오페아': { lv1: '(Q)\'맹독 폭발\'의 견제가 심하므로 무리하게 다가가지 말고 체력 관리에 집중하세요. 첫 웨이브는 최대한 사리며 미니언을 챙기고 (W)\'불안정 물질\'을 활용해 주변 미니언과 함께 피해를 입히며 버텨내세요.', lv3: '(W)\'독기의 늪\'이 빠진 것을 확인한 뒤에 (E)\'새총 발사\'로 진입하세요. 진입 후 (Q)\'탄성 주먹\'으로 상대를 붙잡고 (W)\'불안정 물질\'을 빠르게 사용해 피해를 입히며 조각을 흡수해 체력을 회복하세요.', lv6: '(R)\'바운스!\'로 진입할 때 상대가 (R)\'석화의 응시\'를 사용하면 즉시 몸을 돌려 기절을 피하세요. 정글러를 호출할 때는 (W)\'독기의 늪\'이 빠진 타이밍에 (E)\'새총 발사\'로 빠르게 제압하세요.', item: '헤르메스의 발걸음과 대자연의 힘을 추천해요. 마법 저항력을 높여 (E)\'쌍독니\'의 피해를 줄이고 강인함으로 (R)\'석화의 응시\' 기절 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. 점멸로 (E)\'새총 발사\'의 사거리를 보완하고 점화로 (E)\'쌍독니\'의 체력 회복 효과를 억제하세요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'으로 멀리서 견제하며 (P)\'폭풍의 표식\'을 세 번 쌓아 기절을 걸려고 해요. 표창을 옆으로 피하며 거리를 조절하고, 케넨이 가까이 다가온 순간 (W)\'불안정 물질\'을 사용해 피해를 입히세요. 무리한 진입보다 체력을 보존하며 조각을 흡수해 유지력을 챙기세요.', lv3: '(E)\'번개 질주\'로 빠르게 접근하며 표식을 쌓는 케넨의 움직임을 주의하세요. 케넨의 (E)\'번개 질주\'가 빠진 시점에 (E)\'새총 발사\'로 진입하여 (Q)\'탄성 주먹\'으로 붙잡으면 강하게 압박할 수 있어요. (W)\'전류 방출\'이 사용되어 표식을 추가로 쌓을 수 없는 타이밍을 노려 짧게 교환하고 빠지세요.', lv6: '(R)\'날카로운 소용돌이\'를 켠 케넨은 주변 적에게 반복해서 마법 피해를 주니 너무 오랫동안 근처에 머물지 마세요. 케넨의 궁극기가 끝난 뒤 (R)\'바운스!\'로 진입해 띄워 올리면 정글러와 함께 킬각을 잡기 편해요. (E)\'새총 발사\'로 기습해 상대의 스킬을 먼저 빼놓으면 이후 교전에서 수월하게 대응할 수 있어요.', item: '케이닉 루컨을 첫 코어로 선택해 케넨의 강력한 마법 피해를 견디세요. 신발은 (P)\'폭풍의 표식\'으로 인한 기절 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 인해 걸리는 기절을 정화로 즉시 풀어 대응하세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\' 덕분에 레벨이 오를수록 강력해지는 성장형이라 초반이 가장 약해요. (Q)\'광휘의 일격\'의 사거리가 길어 견제가 들어올 테니 무리하게 맞서기보다 거리를 조절하며 미니언을 챙기세요. (E)\'새총 발사\'를 준비하며 케일이 미니언을 먹으려 할 때 틈을 노려보세요.', lv3: '케일이 (Q)\'광휘의 일격\'으로 방어력을 낮추고 둔화를 걸며 견제할 때 (E)\'새총 발사\'로 빠르게 접근하세요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하거나 (E)\'화염주문검\'을 사용하기 전에 (Q)\'탄성 주먹\'으로 붙어 딜교환을 시작해야 해요. (W)\'불안정 물질\'로 피해를 입히고 조각을 흡수해 체력을 관리하세요.', lv6: '케일의 (R)\'신성한 심판\'은 아군이나 자신을 무적 상태로 만드니 킬각을 잡을 때 궁극기 사용 여부를 반드시 확인해야 해요. 무적 상태에서는 피해가 들어가지 않으니 (R)\'바운스!\'는 무적이 끝난 뒤에 쓰세요. 케일이 성장하기 전에 정글러와 함께 (E)\'새총 발사\'로 압박을 가하는 것이 좋아요.', item: '첫 코어로 케이닉 루컨을 선택해 체력과 마법 저항력을 챙기세요. 신발은 케일의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 케일이 강해지기 전에 점화로 빠르게 격차를 벌리세요.' },
    '코그모': { lv1: '코그모가 (Q)\'부식성 침\'을 사용하여 견제할 때 무리하게 다가가지 마세요. 미니언을 먹으며 체력을 관리하고 (P)\'세포 분열\' 조각을 생성할 기회를 엿봐요. 상대의 사거리 밖에서 안전하게 파밍하며 버티는 것이 중요해요.', lv3: '(E)\'새총 발사\'로 빠르게 접근하여 코그모를 공중으로 띄우는 것이 핵심이에요. 코그모가 (W)\'생체마법 폭격\'을 사용하여 사거리가 늘어난 상태라면 진입에 주의해야 해요. (Q)\'탄성 주먹\'으로 붙잡은 뒤 (W)\'불안정 물질\'을 사용하여 피해를 입히세요.', lv6: '(R)\'바운스!\'를 사용하여 코그모에게 빠르게 접근하여 킬각을 보세요. 코그모가 (R)\'살아있는 곡사포\'를 사용하여 원거리에서 저격할 수 있으니 타이밍을 잘 잡아야 해요. 교전 중에는 (P)\'세포 분열\' 조각을 빠르게 흡수하며 체력을 회복하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 코그모의 마법 피해를 견디며 버티기 위해 선택해요.', spell: '점멸과 점화. 코그모를 확실하게 잡아내기 위해 필요해요.' },
    '코르키': { lv1: '(Q)\'인광탄\' 견제를 받으며 경험치 위주로 행동하세요. (P)\'세포 분열\' 조각을 빠르게 흡수해 체력을 유지하며 버티는 것이 중요해요. 첫 웨이브에서는 무리하게 진입하지 말고 거리 조절을 하세요.', lv3: '(W)\'발키리\'로 도망가기 전에 (Q)\'탄성 주먹\'으로 먼저 둔화시키거나 기습적으로 (E)\'새총 발사\'를 맞히세요. 진입 성공 후 (W)\'불안정 물질\'을 사용해 큰 피해를 입히고 조각을 모으세요. 상대의 (E)\'개틀링 건\'이 닿지 않는 각도에서 진입하는 것이 좋아요.', lv6: '(R)\'바운스!\'를 사용해 거리를 좁히며 진입하고 (R)\'미사일 폭격\'을 피해 빠르게 접근하세요. 상대가 (W)\'발키리\'를 사용해 도망치면 정글러와 함께 추격해 킬각을 잡으세요. 라인을 당겨서 아군 정글의 개입을 유도하는 것이 편해요.', item: '헤르메스의 발걸음과 끝없는 절망을 가세요. 마법 저항력으로 (Q)\'인광탄\' 피해를 줄이고 전투 중 지속적으로 체력을 회복해야 해요.', spell: '점멸과 순간이동을 추천해요. (E)\'새총 발사\'와 점멸을 연계해 기습하고 운영을 통해 손해를 메워야 해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식과 (Q)\'실명 공격\'으로 원거리에서 압박해요. 1~2레벨에는 무리하게 다가가지 말고 (P)\'세포 분열\' 조각을 챙길 수 있는 위치에서 거리를 조절하세요. (Q)\'실명 공격\'에 맞아 시야가 좁아지면 무리한 진입은 피해야 해요.', lv3: '퀸이 (E)\'공중제비\'를 써서 거리를 벌리려고 할 때 (E)\'새총 발사\'를 활용해 진입을 준비하세요. 퀸의 (E)\'공중제비\'가 빠진 직후에 (Q)\'탄성 주먹\'을 맞춰 둔화를 걸고 싸우는 것이 좋아요. (P)\'매사냥\' 표식이 붙은 상태에서의 평타 교환은 피해가 크니 주의하세요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 빠르게 도망가거나 다른 라인을 지원하러 갈 수 있으니 주의하세요. (R)\'바운스!\'를 활용해 퀸을 공중에 띄우고 (W)\'불안정 물질\'로 피해를 입히며 킬각을 보세요. 퀸이 (E)\'공중제비\'로 물러나면 (Q)\'탄성 주먹\'으로 다시 붙어야 해요.', item: '퀸의 기본 공격 피해를 줄이기 위해 판금 장화를 먼저 구매하세요. 첫 코어 아이템으로는 체력을 높여주는 강철심장을 추천해요.', spell: '점멸과 점화를 추천해요. 퀸이 (E)\'공중제비\'로 거리를 벌릴 때 점멸로 추격하고 점화로 마무리하세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 적중시키면 적을 끌어당겨요. (Q)\'탄성 주먹\'으로 거리를 조절하며 (Q)\'엔토포 타격\'의 두 번째 충격파를 맞지 않도록 주의하세요. 1~2레벨에는 무리하게 붙지 말고 조각을 모으며 체력을 관리하세요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전할 때는 저지 불가 상태이므로 (E)\'새총 발사\'로 띄우려 하지 말고 옆으로 피하세요. (E)\'발놀림\'으로 보호막을 얻으며 진입한 크산테에게 (W)\'불안정 물질\'로 최대 체력 비례 피해를 입히며 버티세요. (W)\'길을 여는 자\'의 기절이 빠진 직후에 (Q)\'탄성 주먹\'과 평타 연계로 딜교환을 시도하세요.', lv6: '(R)\'총공세\'를 쓴 크산테는 방어력이 낮아지는 대신 피해량과 회복량이 늘어나니 (R)\'바운스!\'로 밀어내고 둔화시켜 거리를 벌리세요. 벽 근처에 있으면 (R)\'총공세\'에 밀려 벽을 뚫고 날아갈 수 있으니 라인 중앙에서 교전하세요. 크산테가 돌진기를 모두 소모했을 때 (E)\'새총 발사\'로 진입해 정글러와 함께 킬각을 잡으세요.', item: '강철심장을 첫 코어로 선택해 체력을 높여 크산테와의 교환을 오래 버티세요. 신발은 크산테의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 체력 재생과 라인 복귀가 중요한 상황이라 순간이동이 효율적이에요.' },
    '클레드': { lv1: '클레드는 스칼을 타고 있을 때 체력이 많아 초반 몸싸움이 강해요. (Q)\'덫날리기\'에 붙잡힌 채 근처에 머물면 끌려가며 피해를 입으니 즉시 거리를 벌리세요. (Q)\'탄성 주먹\'을 사용하여 클레드를 둔화시키며 첫 웨이브의 피해를 최소화하세요.', lv3: '(E)\'이랴!\'로 빠르게 진입하는 클레드를 (E)\'새총 발사\'로 띄워 돌진 흐름을 끊어주세요. (W)\'버럭버럭\'의 네 번째 평타는 최대 체력 비례 피해가 크니 이 스킬이 켜지면 잠시 거리를 두세요. (Q)\'탄성 주먹\'으로 상대를 붙잡은 뒤 (W)\'불안정 물질\'을 사용하여 체력을 깎고 조각을 흡수해 회복하세요.', lv6: '(R)\'돌겨어어억!!!\'은 보호막을 쓰고 멀리서 돌진해 오니 일직선상에 서 있지 말고 옆으로 피하세요. 클레드가 스칼에서 내려 챔피언 피해량이 줄어든 상태라면 (R)\'바운스!\'로 진입해 연속으로 띄우며 처치하세요. 라인을 당겨 받고 정글러와 함께 (E)\'새총 발사\' 연계로 스칼의 체력을 빠르게 깎으세요.', item: '판금 장화를 신어 클레드의 기본 공격 피해를 줄이세요. 가시 갑옷을 첫 코어로 가서 기본 공격을 하는 클레드에게 피해를 되돌려주고 체력을 높이세요.', spell: '점멸과 순간이동을 추천해요. (E)\'새총 발사\'와 점멸을 연계해 예상치 못한 거리에서 진입하고 라인 복귀를 빠르게 하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓아요. (Q)\'혀 채찍\'은 처음 맞는 유닛을 공격하므로 미니언 뒤에 서서 피해를 피하세요. (W)\'불안정 물질\'로 짧게 딜교환을 하되 (P)\'절대 미각\' 중첩이 다 쌓이기 전에 거리를 벌리세요.', lv3: '(W)\'심연 잠수\'로 들어오는 타이밍을 피해 (E)\'새총 발사\'로 진입하세요. (P)\'절대 미각\' 중첩이 다 쌓이면 (Q)\'혀 채찍\'에 기절하므로, 중첩이 쌓이기 전까지만 (W)\'불안정 물질\'을 사용해 짧게 교환하세요. 상대의 (W)\'심연 잠수\'가 빠진 직후에 공격적으로 움직이세요.', lv6: '(R)\'바운스!\'로 상대를 밀어내고 둔화를 걸어 거리 조절을 하세요. (P)\'절대 미각\' 중첩이 다 쌓인 상태에서 (R)\'집어삼키기\'에 먹히면 큰 피해를 입으니 주의하세요. (E)\'새총 발사\'를 이용해 정글러의 개입에 대비하며 라인을 관리하세요.', item: '공허한 광휘와 헤르메스의 발걸음을 추천해요. 공허한 광휘로 마법 저항력을 높이고, 헤르메스의 발걸음의 강인함으로 (Q)\'혀 채찍\'의 기절과 둔화 지속시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 탐 켄치의 체력 회복을 방해하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하며 초반 평타 교환이 매우 강해요. 무리하게 붙지 말고 (Q)\'탄성 주먹\'으로 견제하며 거리를 유지하세요. (P)\'헌납\' 때문에 미니언 근처에서 싸우면 트런들이 계속 체력을 회복하니 주의하세요.', lv3: '(E)\'얼음 기둥\'에 막히면 (E)\'새총 발사\' 후 후속 동작이 끊길 수 있으니 상대의 기둥 스킬이 빠진 뒤에 진입하세요. (W)\'얼음 왕국\' 영역 안에서는 트런들의 회복량과 공격 속도가 올라가니 영역 밖으로 밀어내거나 피해서 싸우세요. 진입 성공 후에는 (W)\'불안정 물질\'로 최대 체력 비례 피해를 입히고 빠르게 빠지세요.', lv6: '(R)\'진압\'은 자크의 높은 체력과 방어력을 훔치므로 이 스킬에 맞으면 체력이 빠르게 깎여요. (R)\'바운스!\'로 먼저 진입해 적을 띄우고 둔화시킨 뒤 (W)\'불안정 물질\'을 섞어 빠르게 딜교환을 마치세요. 트런들이 (E)\'얼음 기둥\'으로 도망길을 막고 정글러를 부르는 경우가 많으니 라인을 적절히 당기세요.', item: '가시 갑옷과 판금 장화를 추천해요. 가시 갑옷으로 트런들의 평타 공격을 반사하고 (P)\'헌납\'의 회복을 억제하며, 판금 장화로 (Q)\'깨물기\'의 기본 공격 피해를 줄일 수 있어요.', spell: '점멸과 점화를 추천해요. 트런들이 (W)\'얼음 왕국\'과 (P)\'헌납\'으로 회복하는 양이 많으므로 점화의 치유 감소 효과로 마무리하세요.' },
    '트린다미어': { lv1: '트린다미어는 평타로 분노를 모으고 (Q)\'피의 갈망\'으로 체력을 회복하며 강하게 압박해요. (Q)\'탄성 주먹\'으로 적을 맞히며 거리를 조절하고, 무리한 평타 교환보다는 미니언을 챙기며 버티세요. 1~2레벨에는 트린다미어의 치명타 공격을 피하세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 들어오면 (E)\'새총 발사\'로 공중으로 띄워 흐름을 끊으세요. (W)\'조롱의 외침\'에 맞아 이동 속도가 느려지면 무리하게 붙지 말고 (Q)\'탄성 주먹\'으로 거리를 벌리세요. (W)\'불안정 물질\'로 체력 비례 피해를 입히며 딜교환을 하세요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 사용하면 한동안 죽지 않으니 (R)\'바운스!\'를 아껴 두었다가 궁극기가 끝난 뒤에 사용하세요. (R)\'바운스!\'로 진입하여 적을 띄우고 (P)\'세포 분열\' 조각을 흡수하며 체력을 관리하세요. 트린다미어의 궁극기가 끝난 직후에 킬을 노리세요.', item: '첫 코어로 가시 갑옷을 가서 방어력을 높이고 트린다미어의 공격을 견디세요. 신발은 기본 공격으로 받는 피해량을 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 사용하세요. 점화로 트린다미어의 (Q)\'피의 갈망\'을 통한 체력 회복 효과를 줄이세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 계속 독 피해를 입히고 (Q)\'실명 다트\'로 평타를 막아요. (Q)\'실명 다트\'는 대상 지정이라 미니언 뒤에 숨어도 피할 수 없으니 무리하게 진입하지 말고 (Q)\'탄성 주먹\'으로 거리를 재며 체력을 관리하세요. 경험치를 챙기며 버티는 것이 중요해요.', lv3: '(E)\'새총 발사\'로 진입해 공중으로 띄운 뒤 (W)\'불안정 물질\'로 피해를 입히세요. 티모가 (W)\'신속한 이동\'으로 도망치려 하면 (Q)\'탄성 주먹\'을 맞춰 둔화를 거는 게 중요해요. 티모의 (Q)\'실명 다트\'는 평타를 막을 뿐 스킬 피해는 들어오니 계속 압박하세요.', lv6: '(R)\'바운스!\'로 진입해 티모를 띄우면 킬각을 잡을 수 있어요. 하지만 (R)\'유독성 함정\'을 밟으면 둔화와 피해를 입으니 버섯 위치를 조심하세요. 정글러를 불러 덮치되, (P)\'세포 분열\'은 재사용 대기시간이 길어 항상 믿을 수 없으니 체력을 관리하세요.', item: '헤르메스의 발걸음과 정령의 형상을 추천해요. 헤르메스의 발걸음은 (R)\'유독성 함정\'의 둔화 시간을 줄여주고, 정령의 형상은 마법 저항력을 높이며 (P)\'세포 분열\'의 회복량을 늘려줘요.', spell: '점멸과 순간이동을 추천해요. 티모의 견제가 심한 구간을 버티고 운영으로 따라가기 위해 순간이동이 필요해요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 멀리서 견제하며 1~2레벨에 강한 모습을 보여요. 판테온이 (Q)\'혜성의 창\'을 사용하면 거리를 벌려 피해를 줄이고 (P)\'세포 분열\' 조각을 챙기며 버티세요. (P)\'필멸자의 의지\'로 강화된 공격을 맞지 않도록 주의하며 파밍에 집중해요.', lv3: '판테온이 (W)\'방호의 도약\'으로 들어오면 기절에 주의하며 (E)\'새총 발사\'로 맞받아치거나 거리를 조절하세요. 판테온이 (E)\'방패 돌격\'을 사용하면 정면에서는 피해를 줄 수 없으니 옆으로 이동하며 기회를 보세요. 판테온의 (W)\'방호의 도약\'이 빠진 뒤에 (Q)\'탄성 주먹\'으로 딜교환을 시도하세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용하여 공중으로 사라지면 착지 지점을 피하고 다른 라인을 확인하세요. 판테온이 (W)\'방호의 도약\'과 (R)\'거대 유성\'을 모두 사용해 압박한다면 (R)\'바운스!\'로 역습을 노려보세요. 판테온이 궁극기로 합류할 수 있으니 라인을 너무 깊게 밀지 않도록 관리해요.', item: '첫 코어로 체력을 높여주는 강철심장을 가세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. (W)\'방호의 도약\' 이후 이어지는 강력한 피해량을 줄이는 데 도움을 줘요.' },
    '피들스틱': { lv1: '(Q)\'탄성 주먹\'으로 미니언과 함께 적을 견제하며 적정 거리를 유지하세요. 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하여 접근하지 못하도록 와드를 꼼꼼히 설치해요. 초반에는 무리하게 진입하기보다 (P)\'세포 분열\' 조각을 모으는 데 집중하세요.', lv3: '(W)\'풍작\'을 사용하는 피들스틱에게 (E)\'새총 발사\'로 거리를 좁히며 진입하세요. (E)\'수확\'의 중심부에 맞아 침묵을 당하면 스킬을 쓸 수 없으니 주의가 필요해요. (Q)\'탄성 주먹\'으로 적을 붙잡은 뒤 (W)\'불안정 물질\'로 피해를 입히며 딜교환을 진행해요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'으로 진입할 때 (R)\'바운스!\'를 사용하여 적을 공중으로 띄워 방해하세요. (E)\'새총 발사\'로 먼저 진입하여 체력을 깎아둔 뒤 (R)\'바운스!\'를 연계하면 킬각을 잡기 좋아요. 라인을 빠르게 밀어 넣고 적 정글러의 위치를 확인하며 움직이세요.', item: '헤르메스의 발걸음과 정령의 형상을 가세요. 피들스틱의 마법 피해를 견디고 (P)\'세포 분열\'을 통한 체력 회복 효율을 높이기 위해서예요.', spell: '점멸과 유체화. (E)\'새총 발사\'로 접근하기 전에 유체화로 이동 속도를 높이면 더욱 효과적이에요.' },
    '피오라': { lv1: '피오라는 (P)\'치명적인 검무\'로 급소를 가격하면 체력을 회복하고 이동 속도가 오르니 주의하세요. (Q)\'찌르기\'로 들어오는 타이밍을 (Q)\'탄성 주먹\'으로 받아내며 거리를 조절하세요. 초반에는 무리하게 붙지 말고 미니언 사이에서 거리 조절을 하며 피오라의 접근을 경계하세요.', lv3: '피오라가 (W)\'응수\'를 사용하면 모든 공격과 이동 불가 효과를 막아내니 (E)\'새총 발사\'를 아끼세요. (W)\'응수\'가 빠진 후 (E)\'새총 발사\'로 적을 공중에 띄우고 (W)\'불안정 물질\'을 연계하여 딜교환을 하세요. 피오라가 (E)\'대가의 검술\'을 쓰려 하면 (Q)\'탄성 주먹\'으로 둔화시켜 접근을 막으세요.', lv6: '피오라가 (R)\'대결투\'를 사용해 급소를 드러내면 급소 방향을 피해 움직이며 (R)\'바운스!\'로 진입하세요. (R)\'바운스!\'로 적을 공중에 띄운 뒤 (W)\'불안정 물질\'을 연계해 피해를 입히며 킬각을 보세요. 피오라가 급소를 모두 가격하기 전에 정글러를 불러 함께 압박하는 것이 좋아요.', item: '첫 코어로 강철심장을 가서 체력을 확보하세요. 신발은 피오라의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 피오라의 (P)\'치명적인 검무\' 회복 효과를 감소시키세요.' },
    '하이머딩거': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'의 공격을 견디며 경험치만 챙기세요. 포탑 사거리 밖에서 대기하다가 하이머딩거가 무리하게 다가오면 (W)\'불안정 물질\'로 피해를 입히세요. 포탑이 이미 설치된 곳에 억지로 들어가면 피해가 크니 주의하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'에 직격당해 기절하면 포탑 공격에 노출되니 수류탄을 먼저 피하세요. 수류탄이 빠진 뒤 (E)\'새총 발사\'로 빠르게 진입해 하이머딩거를 띄우고 (W)\'불안정 물질\'로 피해를 주세요. (Q)\'탄성 주먹\'으로 하이머딩거를 붙잡아 둔화시키고 포탑 사거리 안에 오래 머물지 않는 게 중요해요.', lv6: '(R)\'업그레이드!!!\'로 강화된 수류탄의 기절 범위가 넓으니 진입할 때 각별히 조심하세요. (R)\'바운스!\'를 사용해 포탑 구역을 빠르게 지나 하이머딩거 본체에 붙어 띄우세요. 하이머딩거가 궁극기를 쓴 직후 첫 스킬이 빠진 틈을 타 정글러와 함께 진입해 킬각을 보세요.', item: '대자연의 힘을 가서 마법 저항력을 높이세요. 마법 피해를 여러 번 받으면 마법 저항력과 이동 속도가 더 늘어나 접근하기 좋아요. 신발은 (E)\'CH-2 전자폭풍 수류탄\'의 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (E)\'새총 발사\'의 사거리를 보완해 하이머딩거를 기습하고 순간이동으로 라인 복귀를 빠르게 하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_zac);
if (typeof module !== 'undefined') module.exports = top_zac;
